    ["Loadouts"] = "Наборы экипировки",
    ["Save and quickly equip gear sets for different specs, content, or roles."] = "Сохраняйте и быстро надевайте наборы экипировки для разных специализаций, контента или ролей.",
    ["Save your current equipment as named gear sets and quickly switch between them. Equipping requires you to be out of combat — items in your bags are auto-equipped via Use."] = "Сохраняйте текущую экипировку как именованные наборы и быстро переключайтесь между ними. Надевать можно только вне боя — предметы из сумок надеваются автоматически через использование.",
