    ["Loadout '%s' already equipped."] = "Набор «%s» уже надет.",
    ["Delete loadout '%s'?"] = "Удалить набор «%s»?",
    ["Cannot change equipment in combat."] = "Нельзя менять экипировку в бою.",
    ["Equipment swap API not available on this client."] = "API смены экипировки недоступен на этом клиенте.",
    ["No loadouts saved yet."] = "Пока нет сохраненных наборов.",
    ["|cffaaaaaaNo loadouts saved yet. Use the button above to save your current gear.|r"] = "|cffaaaaaaПока нет сохраненных наборов. Нажмите кнопку выше, чтобы сохранить текущую экипировку.|r",
    ["Saved loadouts:"] = "Сохраненные наборы:",
    ["Usage: /loadout equip <name> | save <name> | delete <name> | list"] = "Использование: /loadout equip <name> | save <name> | delete <name> | list",
    ["Usage: /loadout delete <name>"] = "Использование: /loadout delete <name>",
    ["|cffaaaaaaSlash commands: /loadout save <name>, /loadout equip <name>, /loadout delete <name>, /loadout list. Short alias: /lo|r"] = "|cffaaaaaaКоманды: /loadout save <name>, /loadout equip <name>, /loadout delete <name>, /loadout list. Короткий вариант: /lo|r",
    ["No account-wide loadouts to import."] = "Нет общих для аккаунта наборов для импорта.",
    ["Imported %d account-wide loadout(s) onto this character."] = "Импортировано общих наборов на этого персонажа: %d.",
    ["You have account-wide loadouts from an older version. Type /lo import to copy them onto this character."] = "У вас есть общие для аккаунта наборы из старой версии. Введите /lo import, чтобы скопировать их на этого персонажа.",
    ["Import from older version"] = "Импорт из старой версии",
    ["|cffaaaaaaYou have gear sets saved account-wide by an older version. Loadouts are now per-character — import copies them onto THIS character.|r"] = "|cffaaaaaaСтарая версия сохранила наборы экипировки для всего аккаунта. Теперь наборы хранятся у каждого персонажа отдельно — импорт скопирует их на ЭТОГО персонажа.|r",
    ["Import account-wide loadouts"] = "Импортировать общие наборы",
    ["Head"] = "Голова",
    ["Chest"] = "Грудь",
    ["Feet"] = "Ступни",
    ["Finger 1"] = "Палец 1",
    ["Trinket 1"] = "Аксессуар 1",
    ["Both trinkets"] = "Оба аксессуара",
    ["Set focus"] = "Назначить фокус",
    ["Healing potion"] = "Лечебное зелье",
    ["Macro Factory"] = "Мастерская макросов",
    ["|cffaaaaaaOne click builds a ready-made macro (per character). Then open |cffffffff/macro|r and drag it onto your action bar. Works on any client — uses item slots / IDs, no English needed.|r"] = "|cffaaaaaaОдно нажатие создает готовый макрос (для этого персонажа). Затем откройте |cffffffff/macro|r и перетащите его на панель команд. Работает на любом клиенте — используются слоты и ID предметов, английский не нужен.|r",
    ["Macro Factory: can't create macros in combat."] = "Мастерская макросов: нельзя создавать макросы в бою.",
    ["Macro Factory: nothing to build (e.g. no healing potion in your bags)."] = "Мастерская макросов: нечего создавать (например, в сумках нет лечебного зелья).",
    ["Macro Factory: couldn't create it (character macro slots full?)."] = "Мастерская макросов: не удалось создать (возможно, слоты макросов персонажа заполнены).",
    ["Macro '%s' updated — drag it from |cffffffff/macro|r onto your action bar."] = "Макрос «%s» обновлен — перетащите его из |cffffffff/macro|r на панель команд.",
    ["Macro '%s' created — open |cffffffff/macro|r and drag it onto your action bar."] = "Макрос «%s» создан — откройте |cffffffff/macro|r и перетащите его на панель команд.",
    ["Back"] = "Назад",
    ["Main Hand"] = "Правая рука",
    ["Save All..."] = "Сохранить все...",
