    ["|cffffffffPOWER BAR|r\n|cffaaaaaaDrag or arrow keys|r"] = "|cffffffffПОЛОСА РЕСУРСА|r\\n|cffaaaaaaПеретаскивание или стрелки|r",
    ["Power Bar mover active. |cff9b6cffDrag the purple box|r or use |cff9b6cffarrow keys|r (SHIFT = 5px). Click 'Unlock / Move' again to finish."] = "Перемещение полосы ресурса включено. |cff9b6cffПеретащите фиолетовый блок|r или используйте |cff9b6cffстрелки|r (SHIFT = 5 пикс.). Нажмите «Разблокировать / Переместить» еще раз, чтобы закончить.",
    ["Power Bar mover disabled."] = "Перемещение полосы ресурса отключено.",
    ["|cffaaaaaaResource bar that follows your class automatically (Mana / Rage / Energy). Druids switch with their form: Bear = Rage, Cat = Energy, otherwise Mana.|r"] = "|cffaaaaaaПолоса ресурса, которая автоматически подстраивается под ваш класс (мана / ярость / энергия). У друидов зависит от облика: медведь = ярость, кошка = энергия, иначе мана.|r",
    ["|cffaaaaaaThe bar colour follows your current power type automatically (Mana = blue, Rage = red, Energy = yellow).|r"] = "|cffaaaaaaЦвет полосы автоматически соответствует текущему типу ресурса (мана = синий, ярость = красный, энергия = желтый).|r",
    ["v%s loaded. /vcui to open."] = "v%s загружен. /vcui для открытия.",
    ["UI not loaded. Likely a Lua error during init. Enable /console scriptErrors 1 and /reload."] = "Интерфейс не загружен. Вероятно, ошибка Lua при запуске. Включите /console scriptErrors 1 и выполните /reload.",
    ["Not possible in combat."] = "Невозможно в бою.",
    ["DB reset. UI reloading."] = "База данных сброшена. Интерфейс перезагружается.",
    ["Debug = %s"] = "Debug = %s",
    ["Registered modules:"] = "Зарегистрированные модули:",
    ["ON"] = "ВКЛ",
    ["off"] = "выкл",
    ["Gold Tracker not active."] = "Учет золота не активен.",
    ["|cffff5555Error while executing:|r %s"] = "|cffff5555Ошибка при выполнении:|r %s",
    ["|cffff5555Event handler error (%s):|r %s"] = "|cffff5555Ошибка обработчика события (%s):|r %s",
    ["WARN: Module '%s' already registered."] = "ВНИМАНИЕ: модуль «%s» уже зарегистрирован.",
    ["|cffff5555Error enabling module '%s':|r %s"] = "|cffff5555Ошибка включения модуля «%s»:|r %s",
    ["|cffff5555Error disabling '%s':|r %s"] = "|cffff5555Ошибка отключения «%s»:|r %s",
    ["Module '%s' disabled. /reload recommended for full effect."] = "Модуль «%s» отключен. Для полного эффекта рекомендуется /reload.",
    ["|cffff5555LibSharedMedia-3.0 not found, Media Registry will be skipped.|r"] = "|cffff5555LibSharedMedia-3.0 не найдена, реестр медиа будет пропущен.|r",
    ["Profiles"] = "Профили",
    ["Manage profiles with different settings. A default profile can be assigned per class and is loaded automatically on login."] = "Управление профилями с разными настройками. Профиль по умолчанию можно назначить для каждого класса, и он загружается автоматически при входе.",
    ["Active Profile"] = "Активный профиль",
    ["You are currently using: |cff9b6cff%s|r  (Class: %s)"] = "Сейчас используется: |cff9b6cff%s|r  (класс: %s)",
    ["Switch Profile"] = "Сменить профиль",
    ["Profile for this character"] = "Профиль для этого персонажа",
    ["|cffaaaaaaPins a profile to THIS character only. At login it beats the class assignment and the account-wide selection - so every character can keep its own minimap, bars and window settings.|r"] = "|cffaaaaaaПривязывает профиль ТОЛЬКО к этому персонажу. При входе он важнее назначения по классу и общего выбора для аккаунта — так каждый персонаж сохраняет свои настройки миникарты, панелей и окон.|r",
    ["This character"] = "Этот персонаж",
    ["Create New Profile"] = "Создать новый профиль",
    ["Name"] = "Название",
    ["Copy Settings From"] = "Скопировать настройки из",
    ["- empty profile (defaults) -"] = "- пустой профиль (по умолчанию) -",
    ["- none -"] = "- нет -",
    ["Create Profile"] = "Создать профиль",
    ["|cffff5555Please enter a name.|r"] = "|cffff5555Введите название.|r",
    ["|cffff5555Please enter a new name.|r"] = "|cffff5555Введите новое название.|r",
    ["Error."] = "Ошибка.",
    ["Manage Current Profile"] = "Управление текущим профилем",
    ["Share Profile"] = "Поделиться профилем",
    ["|cffaaaaaaExport the current profile as a text string - as a backup or to share it. Importing always creates a NEW profile and never overwrites anything.|r"] = "|cffaaaaaaЭкспортируйте текущий профиль в виде текстовой строки — для резервной копии или чтобы поделиться им. Импорт всегда создает НОВЫЙ профиль и никогда ничего не перезаписывает.|r",
    ["Export as string"] = "Экспорт в строку",
    ["Import from string"] = "Импорт из строки",
    ["Copy the profile string (Ctrl+C):"] = "Скопируйте строку профиля (Ctrl+C):",
    ["Paste the profile string:"] = "Вставьте строку профиля:",
    ["This is not a VuloClassicUI profile string."] = "Это не строка профиля VuloClassicUI.",
    ["The profile string is damaged."] = "Строка профиля повреждена.",
    ["Profile '%s' imported. Activate it via 'Switch Profile'."] = "Профиль «%s» импортирован. Активируйте его через «Сменить профиль».",
    ["Manage Profiles"] = "Управление профилями",
    ["Delete..."] = "Удалить...",
    ["Reset to defaults..."] = "Сбросить к настройкам по умолчанию...",
    ["Delete profile '%s'? This cannot be undone."] = "Удалить профиль «%s»? Это действие нельзя отменить.",
    ["Reset profile '%s' to the default settings? This cannot be undone."] = "Сбросить профиль «%s» к настройкам по умолчанию? Это действие нельзя отменить.",
    ["Profile changed. Reload the UI now so every module picks it up?"] = "Профиль изменен. Перезагрузить интерфейс сейчас, чтобы все модули его приняли?",
    ["|cffff5555Profile '%s' could not be loaded:|r %s"] = "|cffff5555Не удалось загрузить профиль «%s»:|r %s",
    ["Rename to"] = "Переименовать в",
    ["Rename"] = "Переименовать",
    ["Delete Active Profile"] = "Удалить активный профиль",
    ["|cffff5555Default profile cannot be deleted.|r"] = "|cffff5555Профиль по умолчанию нельзя удалить.|r",
    ["Apply to Active Class"] = "Применить к текущему классу",
    ["Sets the current profile as the default for %s."] = "Устанавливает текущий профиль как профиль по умолчанию для класса %s.",
    ["'%s' is now the default profile for %s."] = "«%s» теперь профиль по умолчанию для класса %s.",
    ["Per-class profile (quick setup)"] = "Профиль для каждого класса (быстрая настройка)",
    ["Set up a %s profile"] = "Создать профиль для класса %s",
