    ["Profile Assignment per Class"] = "Назначение профилей по классам",
    ["Choose a default profile for each class. When logging in with a character of that class, the profile will be loaded automatically."] = "Выберите профиль по умолчанию для каждого класса. При входе персонажем этого класса профиль загрузится автоматически.",
    ["Settings migrated to profile system (all settings are in profile '%s')."] = "Настройки перенесены в систему профилей (все настройки находятся в профиле «%s»).",
    ["|cffff5555Profile '%s' does not exist.|r"] = "|cffff5555Профиль «%s» не существует.|r",
    ["Profile '%s' created%s."] = "Профиль «%s» создан%s.",
    [" (copy of '%s')"] = " (копия «%s»)",
