    ["Profile does not exist."] = "Профиль не существует.",
    ["Active profile deleted. Default loaded. /reload recommended."] = "Активный профиль удален. Загружен профиль по умолчанию. Рекомендуется /reload.",
    ["Profile '%s' deleted."] = "Профиль «%s» удален.",
    ["Default profile cannot be renamed."] = "Профиль по умолчанию нельзя переименовать.",
