    ["Diminishing Returns Tracker"] = "Отслеживание снижения эффективности (DR)",
    ["Enable DR tracking"] = "Включить отслеживание DR",
    ["INTERRUPTED"] = "ПРЕРВАНО",
    ["Castbar for arena opponents"] = "Полоса заклинания противников на арене",
    ["Collection of simple quality-of-life toggles: auto-accept (quest, res, summon), auto-sell, repair, hide UI spam, text sizes."] = "Набор простых улучшений: автопринятие (задание, воскрешение, призыв), автопродажа, починка, скрытие лишнего в интерфейсе, размеры текста.",
    ["Auto-sold: %d items, +%s"] = "Автопродажа: %d предметов, +%s",
    ["Auto-sold: %d items."] = "Автопродажа: %d предметов.",
    ["Repair exceeds gold (%d < %d)."] = "Починка дороже, чем есть золота (%d < %d).",
    ["Auto-repaired (%dg %ds)."] = "Автопочинка (%dз %dс).",
    ["MAX"] = "МАКС",
    ["General - Auto Actions"] = "Общее — автодействия",
    ["|cffaaaaaaSimple on/off switches for common QoL actions. Take effect immediately, no /reload needed.|r"] = "|cffaaaaaaПростые переключатели для частых удобных действий. Работают сразу, /reload не нужен.|r",
    ["Auto-accept quests"] = "Автопринятие заданий",
    ["Automatically accepts quests when clicking an NPC."] = "Автоматически принимает задания при щелчке по NPC.",
    ["Auto-turn in quests"] = "Автосдача заданий",
    ["Automatically completes finished quests. Waits for user choice on multi-reward quests (no auto-pick)."] = "Автоматически сдает выполненные задания. При выборе из нескольких наград ждет вашего решения (без автовыбора).",
    ["Auto-accept resurrect"] = "Автопринятие воскрешения",
    ["Automatically clicks 'Accept' on resurrect popups (not in combat)."] = "Автоматически нажимает «Принять» в окнах воскрешения (не в бою).",
    ["Auto-accept summon"] = "Автопринятие призыва",
    ["Automatically clicks 'Accept' on warlock/stone summon popups."] = "Автоматически нажимает «Принять» в окнах призыва чернокнижника или камнем призыва.",
    ["Auto-release spirit in PvP/Arena"] = "Автовысвобождение духа в PvP и на арене",
    ["Releases instantly on death in BG or arena."] = "Мгновенно высвобождает дух при смерти на поле боя или арене.",
    ["Auto-sell junk (grey)"] = "Автопродажа хлама (серый)",
    ["Sells all grey items when opening a vendor. Earnings shown in chat."] = "Продает все серые предметы при открытии торговца. Выручка выводится в чат.",
    ["Auto-repair"] = "Автопочинка",
    ["Repairs entire equipment at the vendor if gold is sufficient."] = "Чинит все снаряжение у торговца, если золота хватает.",
    ["Stack-split popup: MAX button"] = "Окно деления стопки: кнопка МАКС",
    ["Adds a 'MAX' button to the quantity popup. Click = buy full stack (at vendor) or split completely (for bag items)."] = "Добавляет кнопку «МАКС» в окно количества. Клик — купить полную стопку (у торговца) или разделить полностью (для предметов в сумке).",
    ["Stack-split popup: VuloUI look"] = "Окно деления стопки: стиль VuloUI",
    ["Restyles the quantity popup (stack buying/splitting) to match the addon look: dark panel, clean buttons and arrows. Turning this off needs a /reload."] = "Меняет стиль окна количества (покупка и деление стопок) под вид аддона: темная панель, аккуратные кнопки и стрелки. Отключение требует /reload.",
    ["Hide UI error messages"] = "Скрыть сообщения об ошибках интерфейса",
    ["Hides the red error messages in the screen center."] = "Скрывает красные сообщения об ошибках в центре экрана.",
    ["Hide zone text"] = "Скрыть название зоны",
    ["Hides the large zone name when entering new areas."] = "Скрывает крупное название зоны при входе в новую местность.",
    ["Hide level numbers on portrait"] = "Скрыть уровень на портрете",
    ["Hides the level display on the Player/Target/Pet portrait."] = "Скрывает отображение уровня на портрете игрока, цели и питомца.",
    ["Hide keybind text on action buttons"] = "Скрыть подписи горячих клавиш на кнопках команд",
    ["Hides the small key labels (1, F1, etc.) on the action buttons."] = "Скрывает мелкие подписи клавиш (1, F1 и т. д.) на кнопках команд.",
    ["Hide macro/spell names on action buttons"] = "Скрыть названия макросов и заклинаний на кнопках команд",
    ["Hides the text labels under the action buttons."] = "Скрывает текстовые подписи под кнопками команд.",
    ["Hide stack/charge numbers on action buttons"] = "Скрыть числа стопок и зарядов на кнопках команд",
    ["Hides the small boxes with numbers at the top right (item stacks, charges, cooldown seconds for long CDs)."] = "Скрывает мелкие рамки с числами в правом верхнем углу (стопки предметов, заряды, секунды длинных восстановлений).",
    ["Hide raid group labels"] = "Скрыть подписи групп рейда",
    ["Mail Text Size"] = "Размер текста почты",
    ["Font size in mail body (opened + sent mail)."] = "Размер шрифта в тексте письма (открытые и отправленные письма).",
    ["Quest Text Size"] = "Размер текста заданий",
    ["Font size in quest descriptions + quest log."] = "Размер шрифта в описаниях заданий и журнале заданий.",
    ["Book Text Size"] = "Размер текста книг",
    ["Font size in readable books and letters from item text."] = "Размер шрифта в читаемых книгах и письмах из текста предметов.",
    ["Queue Timer"] = "Таймер очереди",
    ["Shows a countdown on the PvP/PvE queue pop dialog. Optional sound warning at 5 seconds."] = "Показывает обратный отсчет в окне готовности очереди PvP и PvE. Дополнительно звуковое предупреждение за 5 секунд.",
    ["Queue expires in"] = "Очередь истекает через",
    ["|cff00c0ffQueueTimer:|r "] = "|cff00c0ffQueueTimer:|r ",
    ["Dungeon queue popped instantly!"] = "Очередь в подземелье сработала мгновенно!",
    ["Dungeon queue popped after %s"] = "Очередь в подземелье сработала через %s",
    ["Dungeon queue popped."] = "Очередь в подземелье сработала.",
    ["Queue popped instantly!"] = "Очередь сработала мгновенно!",
    ["Queue popped after %s"] = "Очередь сработала через %s",
    ["Sound on queue pop"] = "Звук при срабатывании очереди",
    ["Plays a sound as soon as the queue pops."] = "Проигрывает звук, как только очередь срабатывает.",
    ["5-second warning"] = "Предупреждение за 5 секунд",
    ["Plays 3 quick sounds when only 5 seconds remain to accept."] = "Проигрывает 3 коротких звука, когда до подтверждения остается всего 5 секунд.",
    ["Hide other timers (e.g. BigWigs)"] = "Скрыть другие таймеры (например, BigWigs)",
    ["Hides foreign StatusBars on the LFG ready popup so only our timer is visible."] = "Скрывает чужие StatusBars в окне готовности поиска группы, чтобы был виден только наш таймер.",
    ["Tooltip IDs"] = "ID в подсказках",
    ["Shows SpellID, ItemID, NPC ID and many other IDs in tooltips (based on idTip by silverwind)."] = "Показывает SpellID, ItemID, NPC ID и множество других ID в подсказках (на основе idTip от silverwind).",
    ["|cff9b6cffTalents:|r "] = "|cff9b6cffТаланты:|r ",
    ["|cff9b6cffiLvL:|r %d"] = "|cff9b6cffУр. предмета:|r %d",
    ["  |cff888888(off by default)|r"] = "  |cff888888(по умолчанию выкл.)|r",
    ["Shows %s in tooltips."] = "Показывает %s в подсказках.",
    ["Shows additional ID lines in tooltips, e.g. spell, item or NPC IDs."] = "Показывает дополнительные строки с ID в подсказках, например ID заклинаний, предметов или NPC.",
    ["Quick Select"] = "Быстрый выбор",
    ["All on"] = "Включить все",
    ["All off"] = "Выключить все",
    ["Defaults"] = "По умолчанию",
    ["Player Tooltip (Inspect-based)"] = "Подсказка игрока (на основе осмотра)",
    ["|cffaaaaaaWhen you hover over a player, their average iLvL + talent distribution (e.g. 14/0/47) is shown in the tooltip. Data is cached 60s per player, inspect throttle 1/s.|r"] = "|cffaaaaaaПри наведении на игрока в подсказке показывается его средний уровень предметов и распределение талантов (например, 14/0/47). Данные кэшируются 60 с на игрока, ограничение осмотра — 1/с.|r",
    ["Show average iLvL"] = "Показывать средний уровень предметов",
    ["Show talent distribution (e.g. 14/0/47)"] = "Показывать распределение талантов (например, 14/0/47)",
    ["ID Types"] = "Типы ID",
    ["Which IDs should be shown in tooltips? Some types are only active in Retail and are ignored in TBC (e.g. TraitNodeID, SourceID)."] = "Какие ID показывать в подсказках? Некоторые типы работают только в Retail и игнорируются в TBC (например, TraitNodeID, SourceID).",
    ["Auto Item Buy"] = "Автопокупка предметов",
    ["Automatically buys configured items at configured vendors. Shift when opening the merchant window = emergency stop."] = "Автоматически покупает заданные предметы у заданных торговцев. Shift при открытии окна торговца — экстренная остановка.",
    ["|cffffd200[AutoItemBuy]|r "] = "|cffffd200[AutoItemBuy]|r ",
    ["Buying: "] = "Покупка: ",
    ["Close merchant window after purchase"] = "Закрывать окно торговца после покупки",
    ["Closes the merchant window automatically ~0.2s after purchase."] = "Закрывает окно торговца автоматически примерно через 0.2 с после покупки.",
    ["Chat message on each purchase"] = "Сообщение в чат о каждой покупке",
    ["|cffaaaaaaTip: Hold SHIFT when opening the merchant window to skip automatic purchase once.|r"] = "|cffaaaaaaСовет: удерживайте SHIFT при открытии окна торговца, чтобы один раз пропустить автопокупку.|r",
    ["Add Vendor"] = "Добавить торговца",
    ["Vendor Name"] = "Имя торговца",
    ["Add"] = "Добавить",
    ["|cffff5555Please enter a vendor name.|r"] = "|cffff5555Введите имя торговца.|r",
    ["|cffff5555Vendor '%s' already exists.|r"] = "|cffff5555Торговец «%s» уже существует.|r",
    ["Vendor '%s' added."] = "Торговец «%s» добавлен.",
    ["Manage Vendors"] = "Управление торговцами",
    ["|cffaaaaaaNo vendors added yet. Add a vendor above, then select it here to configure items.|r"] = "|cffaaaaaaТорговцы еще не добавлены. Добавьте торговца выше, затем выберите его здесь, чтобы настроить предметы.|r",
    ["Currently selected vendor"] = "Текущий выбранный торговец",
    ["Delete this vendor"] = "Удалить этого торговца",
    ["Vendor '%s' removed."] = "Торговец «%s» удален.",
    ["Items at '%s'"] = "Предметы у «%s»",
    ["Shows a friendly NPC's subtitle (e.g. <Innkeeper>) under its name in name-only mode."] = "Показывает титул дружественного НИП (например, <Трактирщик>) под именем в режиме «только имя».",
    ["<Innkeeper>"] = "<Трактирщик>",
    ["Nameplates"] = "Индикаторы здоровья",
    ["Vulo Classes"] = "Vulo Classes",
    ["Vulo Fantasy 1"] = "Vulo Fantasy 1",
    ["Vulo Fantasy 2"] = "Vulo Fantasy 2",
    ["Vulo Epic"] = "Vulo Epic",
    ["Fade, mouseover-reveal, combat visibility, scale and a custom grid layout for each action bar. The default Blizzard layout is untouched until you change a bar below."] = "Затухание, показ при наведении, видимость в бою, масштаб и своя сетка для каждой панели команд. Стандартный макет Blizzard не меняется, пока вы не измените панель ниже.",
    ["|cffaaaaaaFade, mouseover-reveal, combat visibility, scale and a custom grid layout for each bar. Visibility uses opacity, so it never taints and works in combat. The default layout stays untouched until you change a bar.|r"] = "|cffaaaaaaЗатухание, показ при наведении, видимость в бою, масштаб и своя сетка для каждой панели. Видимость работает через непрозрачность, поэтому не портит защищенный код и работает в бою. Стандартный макет не меняется, пока вы не измените панель.|r",
    ["Main Bar"] = "Основная панель",
    ["Bottom Bar 1"] = "Нижняя панель 1",
    ["Bottom Bar 2"] = "Нижняя панель 2",
    ["Right Bar 1"] = "Правая панель 1",
    ["Right Bar 2"] = "Правая панель 2",
    ["Stance Bar"] = "Панель стоек",
    ["Pet Bar"] = "Панель питомца",
    ["Always shown"] = "Всегда видна",
    ["Mouseover"] = "При наведении",
    ["In combat"] = "В бою",
    ["Out of combat"] = "Вне боя",
    ["Faded opacity"] = "Непрозрачность при затухании",
    ["The bar's opacity when hidden by mouseover or combat visibility (0 = invisible)."] = "Непрозрачность панели, когда она скрыта наведением или видимостью в бою (0 = невидима).",
    ["Fade speed (sec.)"] = "Скорость затухания (сек.)",
    ["Takes over the action bars: own bar frames with real show/hide, scale and custom layout. Disabling restores Blizzard's default bars."] = "Берет панели команд под свое управление: собственные рамки панелей с настоящим показом/скрытием, масштабом и своим макетом. Отключение возвращает стандартные панели Blizzard.",
    ["|cffaaaaaaThis takes over your action bars with real show/hide, scale and custom layout. Disabling the module restores Blizzard's default bars. Changes to bars apply out of combat.|r"] = "|cffaaaaaaМодуль берет ваши панели команд под свое управление: настоящий показ/скрытие, масштаб и свой макет. Отключение модуля возвращает стандартные панели Blizzard. Изменения панелей применяются вне боя.|r",
    ["The bar's opacity when hidden by mouseover (0 = invisible)."] = "Непрозрачность панели, когда она скрыта наведением (0 = невидима).",
    ["|cffff5555Action Bars: leaving combat to restore Blizzard's bars…|r"] = "|cffff5555Панели команд: ожидание выхода из боя для восстановления панелей Blizzard…|r",
    ["Replaces the main action bar with its own buttons: real combat/mouseover show-hide, scale and grid layout, correct paging (druid/rogue/warrior/priest forms) and your keybinds. EXPERIMENTAL — test ability clicks and paging in combat; /reload after disabling."] = "Заменяет основную панель команд собственными кнопками: настоящий показ/скрытие в бою и при наведении, масштаб и сетка, правильное переключение страниц (формы друида/разбойника/воина/жреца) и ваши горячие клавиши. ЭКСПЕРИМЕНТАЛЬНО — проверьте нажатие способностей и смену страниц в бою; после отключения введите /reload.",
    ["|cffaaaaaaReplaces the MAIN action bar with its own buttons: real combat / mouseover show-hide, scale and grid layout, correct paging (druid/rogue/warrior/priest forms) and your keybinds. EXPERIMENTAL: test ability clicks and form-switching in combat. After disabling, type /reload to fully restore Blizzard's bar. The other bars are unchanged for now.|r"] = "|cffaaaaaaЗаменяет ОСНОВНУЮ панель команд собственными кнопками: настоящий показ/скрытие в бою и при наведении, масштаб и сетка, правильное переключение страниц (формы друида/разбойника/воина/жреца) и ваши горячие клавиши. ЭКСПЕРИМЕНТАЛЬНО: проверьте нажатие способностей и смену форм в бою. После отключения введите /reload, чтобы полностью вернуть панель Blizzard. Остальные панели пока не затрагиваются.|r",
    ["|cffff5555Action Bars: leaving combat to restore Blizzard's bar…|r"] = "|cffff5555Панели команд: ожидание выхода из боя для восстановления панели Blizzard…|r",
    ["|cffffcc00Action Bars disabled — type /reload to fully restore the default bar.|r"] = "|cffffcc00Панели команд отключены — введите /reload, чтобы полностью вернуть стандартную панель.|r",
    ["Horizontal position"] = "Положение по горизонтали",
    ["Vertical position"] = "Положение по вертикали",
    ["|cff9b6cffMove and scale each bar in Edit Mode — type /vedit (or open Blizzard's Edit Mode), then drag the bar's box.|r"] = "|cff9b6cffПеремещайте и масштабируйте каждую панель в Режиме редактирования — введите /vedit (или откройте Режим редактирования Blizzard), затем перетащите блок панели.|r",
    ["|cffaaaaaaReplaces the MAIN action bar with its own buttons: real combat / mouseover show-hide, scale and grid layout, correct paging (druid/rogue/warrior/priest forms) and your keybinds. Move it in Edit Mode (/vedit). After disabling, /reload to fully restore Blizzard's bar.|r"] = "|cffaaaaaaЗаменяет ОСНОВНУЮ панель команд собственными кнопками: настоящий показ/скрытие в бою и при наведении, масштаб и сетка, правильное переключение страниц (формы друида/разбойника/воина/жреца) и ваши горячие клавиши. Перемещается в Режиме редактирования (/vedit). После отключения введите /reload, чтобы полностью вернуть панель Blizzard.|r",
    ["|cffaaaaaaOwn buttons for every action bar (1-5): real combat / mouseover show-hide, scale and grid layout, correct main-bar paging (druid/rogue/warrior/priest forms) and your keybinds. Move each in Edit Mode (/vedit). After disabling, /reload to fully restore Blizzard's bars.|r"] = "|cffaaaaaaСобственные кнопки для каждой панели команд (1-5): настоящий показ/скрытие в бою и при наведении, масштаб и сетка, правильное переключение страниц основной панели (формы друида/разбойника/воина/жреца) и ваши горячие клавиши. Каждая перемещается в Режиме редактирования (/vedit). После отключения введите /reload, чтобы полностью вернуть панели Blizzard.|r",
    ["|cff9b6cffThe stance and pet bars are still Blizzard's native bars — arrange those with Blizzard's Edit Mode for now.|r"] = "|cff9b6cffПанели стоек и питомца по-прежнему стандартные панели Blizzard — пока размещайте их через Режим редактирования Blizzard.|r",
    ["|cff9b6cffThe pet bar is still Blizzard's native bar — arrange it with Blizzard's Edit Mode for now.|r"] = "|cff9b6cffПанель питомца по-прежнему стандартная панель Blizzard — пока размещайте ее через Режим редактирования Blizzard.|r",
    ["Action Bar 1 (Main)"] = "Панель команд 1 (основная)",
    ["Action Bar 2"] = "Панель команд 2",
    ["Action Bar 3"] = "Панель команд 3",
    ["Action Bar 4"] = "Панель команд 4",
    ["Action Bar 5"] = "Панель команд 5",
    ["Action Bar 6 (Extra)"] = "Панель команд 6 (дополнительная)",
    ["Grow from"] = "Расти от",
    ["Left edge (rightwards)"] = "Левого края (вправо)",
    ["Right edge (leftwards)"] = "Правого края (влево)",
    ["Rows grow"] = "Ряды растут",
    ["Mouseover reveals all mouseover bars"] = "Наведение показывает все панели с наведением",
    ["Hovering ANY mouseover bar shows every bar set to mouseover at once."] = "Наведение на ЛЮБУЮ панель с режимом наведения сразу показывает все такие панели.",
    ["Button text styling"] = "Оформление текста кнопок",
    ["|cffaaaaaaColours and fine offsets for the button texts, on every bar.|r"] = "|cffaaaaaaЦвета и точные смещения текстов на кнопках всех панелей.|r",
    ["Keybind text colour"] = "Цвет текста горячих клавиш",
    ["Macro text colour"] = "Цвет текста макросов",
    ["Count text colour"] = "Цвет текста количества",
    ["Keybind offset X"] = "Смещение горячей клавиши по X",
    ["Keybind offset Y"] = "Смещение горячей клавиши по Y",
    ["Macro offset X"] = "Смещение макроса по X",
    ["Macro offset Y"] = "Смещение макроса по Y",
    ["Count offset X"] = "Смещение количества по X",
    ["Count offset Y"] = "Смещение количества по Y",
    ["|cff9b6cffThe other bars (2-5, stance, pet) are Blizzard's protected Edit Mode bars — an addon can't move them without errors. Use Blizzard's Edit Mode to place and size those.|r"] = "|cff9b6cffОстальные панели (2-5, стоек, питомца) — защищенные панели Режима редактирования Blizzard, аддон не может переместить их без ошибок. Используйте Режим редактирования Blizzard, чтобы разместить их и задать размер.|r",
    ["0 = use the game's default size."] = "0 = использовать стандартный размер игры.",
    ["Vertical layout"] = "Вертикальный макет",
    ["Reverse order"] = "Обратный порядок",
    ["Hide keybind text"] = "Скрыть текст горячих клавиш",
    ["Hide macro text"] = "Скрыть текст макросов",
    ["Game Menu"] = "Игровое меню",
    ["Game menu: VuloUI look"] = "Игровое меню: стиль VuloUI",
    ["Restyles the Escape menu to match the addon look: dark panel, flat buttons, accent title. Changing this needs a /reload."] = "Меняет оформление меню Escape под стиль аддона: темная панель, плоские кнопки, акцентный заголовок. Изменение требует /reload.",
    ["Game menu: VuloClassicUI button"] = "Игровое меню: кнопка VuloClassicUI",
    ["Adds a VuloClassicUI button to the Escape menu that opens the options window. Turning this off needs a /reload."] = "Добавляет в меню Escape кнопку VuloClassicUI, открывающую окно настроек. Отключение требует /reload.",
    ["Hide the FPS / latency bar"] = "Скрыть панель FPS / задержки",
    ["Hides Blizzard's small green performance (FPS / latency) bar."] = "Скрывает маленькую зеленую панель производительности Blizzard (FPS / задержка).",
    ["Micro menu style"] = "Стиль микроменю",
    ["World map"] = "Карта мира",
    ["Friends list"] = "Список друзей",
    ["Group finder"] = "Поиск группы",
    ["Shop"] = "Магазин",
    ["Bag bar style"] = "Стиль панели сумок",
    ["Key ring"] = "Связка ключей",
    ["Timer decimals below 10 seconds"] = "Доли секунды на таймере до 10 секунд",
    ["Interrupted by %s"] = "Прервано: %s",
    ["Value + percent"] = "Значение + процент",
    ["Value + percent layout"] = "Макет «значение + процент»",
    ["Short values (12.3k)"] = "Короткие значения (12,3 тыс.)",
    ["Show percent sign"] = "Показывать знак процента",
    ["Smooth health changes"] = "Плавное изменение здоровья",
    ["The bar glides to the new value; a bright trail marks health draining away."] = "Полоса плавно движется к новому значению; яркий след отмечает утекающее здоровье.",
    ["Tint background with bar colour"] = "Окрашивать фон цветом полосы",
    ["The empty part of the bar shows a darkened shade of the bar colour instead of plain dark grey."] = "Пустая часть полосы окрашивается затемненным оттенком цвета полосы вместо простого темно-серого.",
    ["Glow at the bar edge"] = "Свечение на краю полосы",
    ["A soft glow rides the end of the fill, tinted in the bar's own colour. Also applies to the cast bar."] = "Мягкое свечение движется по краю заполнения в цвет самой полосы. Также применяется к полосе заклинания.",
    ["Edge glow width"] = "Ширина свечения края",
    ["Rounded bar corners"] = "Скругленные углы полосы",
    ["Overall plate scale (%)"] = "Общий масштаб индикаторов (%)",
    ["Scales every plate at once, on top of each individual size."] = "Масштабирует все индикаторы сразу, поверх индивидуальных размеров.",
    ["Vertical offset"] = "Смещение по вертикали",
    ["Moves every plate up or down relative to its unit."] = "Смещает все индикаторы вверх или вниз относительно их существ.",
    ["Font outline"] = "Контур шрифта",
    ["How plate text is lifted off the background."] = "Насколько текст индикаторов отделен от фона.",
    ["Thick outline"] = "Толстый контур",
    ["Show level"] = "Показывать уровень",
    ["Shows the unit level to the left of the name; ?? means the level is far above yours."] = "Показывает уровень существа слева от имени; ?? означает, что уровень намного выше вашего.",
    ["Mark rare and elite"] = "Отмечать редких и элитных",
    ["Appends a rank to the level and turns it gold: + elite, R rare, R+ rare elite, B world boss."] = "Добавляет к уровню ранг и красит его в золотой: + элитный, R редкий, R+ редкий элитный, B мировой босс.",
    ["Level size"] = "Размер уровня",
    ["0 = uses the name size."] = "0 = использует размер имени.",
    ["Emphasise casting units"] = "Выделять произносящих заклинание",
    ["While a unit casts, its plate grows a little and stays readable even when something else is targeted."] = "Пока существо читает заклинание, его индикатор немного увеличивается и остается читаемым, даже если выбрана другая цель.",
    ["Casting scale (%)"] = "Масштаб при произнесении (%)",
    ["Casting opacity (%)"] = "Непрозрачность при произнесении (%)",
    ["Flash before running out"] = "Мигание перед окончанием",
    ["The icon pulses over the last part of its duration, so you can see when to refresh."] = "Значок пульсирует в конце своего действия, чтобы вы видели, когда обновить эффект.",
    ["Flash below (%)"] = "Мигание ниже (%)",
    ["Debuff Row"] = "Ряд отрицательных эффектов",
    ["Buff Row"] = "Ряд эффектов",
    ["Your Own Debuffs"] = "Ваши отрицательные эффекты",
    ["|cffaaaaaaA separate row for the harmful auras you cast yourself - your damage-over-time timers, kept away from everything else on the target.|r"] = "|cffaaaaaaОтдельный ряд для вредоносных эффектов, наложенных вами, — ваши таймеры периодического урона, отделенные от всего остального на цели.|r",
    ["Show your own debuffs (separate row)"] = "Показывать ваши отрицательные эффекты (отдельный ряд)",
    ["Max icons"] = "Макс. значков",
    ["Above the plate"] = "Над индикатором",
    ["Below the plate"] = "Под индикатором",
    ["Which end of the plate this row sits on. Rows on the same side queue up outward."] = "С какой стороны индикатора находится этот ряд. Ряды с одной стороны выстраиваются наружу.",
    ["Grow"] = "Рост",
    ["Centred"] = "По центру",
    ["Which way the icons run. Left and right line the row up with the matching edge of the health bar."] = "В какую сторону идут значки. «Влево» и «вправо» выравнивают ряд по соответствующему краю полосы здоровья.",
    ["Icons per line"] = "Значков в строке",
    ["0 = one line. Otherwise the row wraps after this many icons."] = "0 = одна строка. Иначе ряд переносится после этого количества значков.",
    ["Reminders"] = "Напоминания",
    ["|cffaaaaaaShows a short row of icons for what you are missing right now. Out of combat a click casts or uses the fix; hovering explains what it wants. The row holds still during combat.|r"] = "|cffaaaaaaПоказывает короткий ряд значков с тем, чего вам сейчас не хватает. Вне боя щелчок применяет нужное действие, а наведение поясняет, чего не хватает. В бою ряд остается неподвижным.|r",
    ["Also warn about empty equipment slots"] = "Предупреждать и о пустых ячейках экипировки",
    ["Off by default: a ring, trinket or cloak is often legitimately empty while levelling."] = "По умолчанию выключено: кольцо, аксессуар или плащ во время прокачки часто пусты вполне обоснованно.",
    ["Shows what you are missing - class buffs, weapon enchants, food, stance, pet, ammo, durability, empty gear slots and unspent talent points."] = "Показывает, чего вам не хватает: классовых эффектов, чар на оружии, еды, стойки, питомца, боеприпасов, прочности, пустых ячеек экипировки и нераспределенных очков талантов.",
    ["What to watch"] = "Что отслеживать",
    ["Class buffs"] = "Классовые эффекты",
    ["Weapon enchants"] = "Чары на оружии",
    ["Stance and aura"] = "Стойка и аура",
    ["Food and flask"] = "Еда и настой",
    ["Ammo, durability, gear, talents"] = "Боеприпасы, прочность, экипировка, таланты",
    ["Most icons at once"] = "Макс. значков одновременно",
    ["Anything past this is bundled into a single counter instead of adding another icon."] = "Все сверх этого объединяется в один счетчик вместо добавления новых значков.",
    ["Show labels"] = "Показывать подписи",
    ["Settle time (seconds)"] = "Задержка появления (секунды)",
    ["How long something must stay missing before an icon appears. Stops it flickering between casts."] = "Сколько времени чего-то должно не хватать, прежде чем появится значок. Не дает значкам мигать между заклинаниями.",
    ["Warn when under (seconds)"] = "Предупреждать при остатке (секунды)",
    ["Also warn while a buff or weapon enchant is about to run out. 0 = only warn when it is gone."] = "Также предупреждать, когда эффект или чары на оружии скоро закончатся. 0 = предупреждать, только когда их нет.",
    ["Durability below (%)"] = "Прочность ниже (%)",
    ["Ammo below"] = "Боеприпасов меньше",
    ["Quiet while resting"] = "Молчать на отдыхе",
    ["No reminders in a city or inn."] = "Никаких напоминаний в городе или на постоялом дворе.",
    ["Quiet while eating or drinking"] = "Молчать во время еды и питья",
    ["Click to cast."] = "Щелкните, чтобы применить.",
    ["Missing: %s"] = "Не хватает: %s",
    ["Main hand"] = "Правая рука",
    ["Off hand"] = "Левая рука",
    ["No weapon enchant: %s"] = "Нет чар на оружии: %s",
    ["Weapon enchant running out: %s"] = "Чары на оружии заканчиваются: %s",
    ["Stance"] = "Стойка",
    ["No stance active"] = "Стойка не активна",
    ["Aura"] = "Аура",
    ["No aura active"] = "Аура не активна",
    ["Pet"] = "Питомец",
    ["No pet out"] = "Питомец не призван",
    ["Passive"] = "Пассивный",
    ["Pet is set to passive"] = "Питомец в пассивном режиме",
    ["Food"] = "Еда",
    ["Not well fed"] = "Нет эффекта сытости",
    ["Flask"] = "Настой",
    ["No flask or elixir"] = "Нет настоя или эликсира",
    ["Low ammo: %d left"] = "Мало боеприпасов: осталось %d",
    ["Equipment damaged: %d%% left"] = "Экипировка повреждена: осталось %d%%",
    ["Empty equipment slots: %d"] = "Пустых ячеек экипировки: %d",
    ["Unspent talent points: %d"] = "Нераспределенных очков талантов: %d",
    ["Racials"] = "Расовые способности",
    ["Racial Cooldowns"] = "Восстановление расовых способностей",
    ["Shows the opponent's racial ability and its cooldown once they use it. These are this expansion's cooldowns, and no racial shares one with the PvP trinket yet."] = "Показывает расовую способность противника и ее восстановление, как только он ее применит. Это восстановления текущего дополнения, и ни одна расовая способность пока не делит восстановление с PvP-аксессуаром.",
    ["Show racial cooldown"] = "Показывать восстановление расовой способности",
    ["Shadow Sight"] = "Темное зрение",
    ["Shadow Sight up"] = "Темное зрение активно",
    ["Shadow Sight up - next in %d s"] = "Темное зрение активно — следующее через %d с",
    ["Shadow Sight in %d s"] = "Темное зрение через %d с",
    ["Counts down the arena orbs: the first pair appears 95 seconds after the gates open, and each one returns 122 seconds after it is taken."] = "Отсчитывает время до сфер на арене: первая пара появляется через 95 секунд после открытия ворот, и каждая возвращается через 122 секунды после того, как ее взяли.",
    ["Show Shadow Sight timer"] = "Показывать таймер Темного зрения",
    ["Aura on the class icon"] = "Эффект на значке класса",
    ["Puts the single most relevant aura on the opponent's class icon: an immunity outranks crowd control, which outranks a defensive, which outranks an offensive cooldown."] = "Помещает на значок класса противника один самый важный эффект: неуязвимость важнее контроля, контроль важнее защитной способности, а та важнее атакующей.",
    ["Show aura on the class icon"] = "Показывать эффект на значке класса",
    ["Crowd control only"] = "Только контроль",
    ["Dispels"] = "Рассеивание",
    ["Dispel Cooldowns"] = "Восстановление рассеивания",
    ["|cffaaaaaaMost dispels have no cooldown in this expansion, so only Mass Dispel and the felhunter's Devour Magic can ever show up here.|r"] = "|cffaaaaaaУ большинства способов рассеивания в этом дополнении нет восстановления, поэтому здесь могут появиться только «Массовое рассеивание» и «Пожирание магии» ищейки Скверны.|r",
    ["Show dispel cooldown"] = "Показывать восстановление рассеивания",
    ["Range"] = "Дальность",
    ["Fades the frame while the opponent is out of reach, measured with a spell your class knows rather than a fixed distance."] = "Приглушает рамку, пока противник вне досягаемости; расстояние определяется по заклинанию вашего класса, а не по фиксированной дистанции.",
    ["Fade out-of-range opponents"] = "Приглушать противников вне досягаемости",
    ["Discard changes and revert every window to the last save point, or to how it was when Edit Mode opened."] = "Отменить изменения и вернуть все окна к последнему сохранению или к состоянию на момент открытия Режима редактирования.",
    ["Discard all changes made since the last save?"] = "Отменить все изменения, сделанные после последнего сохранения?",
    ["Grey out when you walk out of range"] = "Обесцвечивать при выходе из радиуса",
    ["Drains the colour while you are outside a totem's radius, and restores it when you step back in. Recognised from the buff the totem puts on you, so totems that grant no buff (Searing, Magma, Tremor, ...) always stay lit."] = "Убирает цвет, пока вы находитесь вне радиуса тотема, и возвращает его, когда вы возвращаетесь. Определяется по эффекту, который тотем накладывает на вас, поэтому тотемы без эффекта (испепеления, магмы, дрожи земли, ...) всегда остаются яркими.",
    ["Limit to"] = "Ограничить",
    ["Everything"] = "Все",
    ["Only mine"] = "Только мои",
    ["Only removable"] = "Только снимаемые",
    ["Narrows this row to auras you cast yourself, or to ones that can be removed."] = "Сужает этот ряд до эффектов, наложенных вами, или до тех, которые можно снять.",
    ["Nudges every aura row at once, on top of each row's own offset."] = "Сдвигает все ряды эффектов сразу, поверх собственного смещения каждого ряда.",
    ["Share of the remaining duration at which the pulse starts."] = "Доля оставшегося времени действия, при которой начинается пульсация.",
    ["Own colour while your interrupt is ready"] = "Свой цвет, когда ваше прерывание готово",
    ["Interruptible casts paint in this colour while your interrupt is off cooldown — kick at will."] = "Прерываемые заклинания окрашиваются в этот цвет, пока ваше прерывание не на восстановлении — можно прерывать в любой момент.",
    ["Interrupt-ready colour"] = "Цвет готового прерывания",
    ["Own colour while channelling"] = "Свой цвет при поддерживаемом заклинании",
    ["Channel colour"] = "Цвет поддерживаемого заклинания",
    ["Own colour when the cast targets YOU"] = "Свой цвет, когда заклинание нацелено на ВАС",
