    ["On: 9.9, 3.4 … Off: whole seconds (9, 3)."] = "Вкл.: 9,9, 3,4 … Выкл.: целые секунды (9, 3).",
    ["Modern puts the real bag buttons on a flat dark strip in the VuloUI look — opening, swapping and tooltips stay identical."] = "«Современный» помещает настоящие кнопки сумок на плоскую темную полосу в стиле VuloUI — открытие, замена и подсказки не меняются.",
    ["Modern replaces Blizzard's buttons with a flat dark icon strip in the VuloUI look. Clicks and tooltips stay identical."] = "«Современный» заменяет кнопки Blizzard плоской темной полосой значков в стиле VuloUI. Щелчки и подсказки не меняются.",
    ["Classic (Blizzard buttons)"] = "Классический (кнопки Blizzard)",
    ["Modern (flat icon strip)"] = "Современный (плоская полоса значков)",
    ["Hides the row of menu buttons (character, spellbook, …)."] = "Скрывает ряд кнопок меню (персонаж, книга заклинаний, …).",
    ["Hide the bag bar"] = "Скрыть панель сумок",
