    ["Hide without enemy target"] = "Скрывать без враждебной цели",
    ["Quick keybind mode (/vkb)"] = "Режим быстрого назначения клавиш (/vkb)",
    ["Hover an action button and press a key to bind it. Hidden bars are shown while binding."] = "Наведите курсор на кнопку и нажмите клавишу, чтобы назначить ее. Скрытые панели показываются на время назначения.",
    ["Swipe colour"] = "Цвет затемнения восстановления",
    ["Icon opacity on cooldown"] = "Непрозрачность значка при восстановлении",
    ["Dims the whole icon while the ability is on cooldown (100 = off)."] = "Приглушает весь значок, пока способность на восстановлении (100 = выкл.).",
    ["Show cooldown numbers"] = "Показывать числа восстановления",
    ["The game's own countdown numbers on cooldowns (a game setting, changed live)."] = "Собственные числа обратного отсчета игры на восстановлениях (настройка игры, применяется сразу).",
    ["|cffaaaaaaApplies to every action bar.|r"] = "|cffaaaaaaПрименяется ко всем панелям команд.|r",
    ["Cooldown swipe opacity"] = "Непрозрачность затемнения восстановления",
    ["How dark the cooldown sweep overlay is (0 = invisible)."] = "Насколько темным будет наложение отсчета восстановления (0 = невидимо).",
    ["Desaturate icons on cooldown"] = "Обесцвечивать значки при восстановлении",
    ["Out-of-range colouring"] = "Окраска вне досягаемости",
    ["Tints the whole icon while your target is out of range."] = "Окрашивает весь значок, пока ваша цель вне досягаемости.",
    ["Tooltips"] = "Подсказки",
    ["Hide in combat"] = "Скрывать в бою",
    ["Hide always"] = "Скрывать всегда",
    ["A movable, resizable experience bar with rested overlay. Hidden at max level."] = "Перемещаемая полоса опыта с изменяемым размером и зоной отдохнувшего опыта. Скрыта на максимальном уровне.",
    ["A movable, resizable experience bar with rested overlay. Hidden at max level. Replaces Blizzard's bar while on."] = "Перемещаемая полоса опыта с изменяемым размером и зоной отдохнувшего опыта. Скрыта на максимальном уровне. Пока включена, заменяет полосу Blizzard.",
    ["Hide Blizzard's XP / reputation bar"] = "Скрыть полосу опыта / репутации Blizzard",
    ["Removes the leftover blue experience / reputation bar under the action bar."] = "Убирает оставшуюся синюю полосу опыта / репутации под панелью команд.",
    ["Main bar"] = "Основная панель",
    ["Bottom left bar"] = "Нижняя левая панель",
    ["Bottom right bar"] = "Нижняя правая панель",
    ["Right bar"] = "Правая панель",
    ["Left bar"] = "Левая панель",
    ["Stance bar"] = "Панель стоек",
    ["Pet bar"] = "Панель питомца",
    ["Takes over every action bar with its own movable frames: real combat/mouseover show-hide, scale and grid layout per bar, correct main-bar paging (druid/rogue/warrior/priest forms) and your keybinds. EXPERIMENTAL — test ability clicks and paging in combat; /reload after disabling."] = "Берет все панели команд под свое управление собственными перемещаемыми рамками: настоящий показ/скрытие в бою и при наведении, масштаб и сетка для каждой панели, правильное переключение страниц основной панели (формы друида/разбойника/воина/жреца) и ваши горячие клавиши. ЭКСПЕРИМЕНТАЛЬНО — проверьте нажатие способностей и смену страниц в бою; после отключения введите /reload.",
    ["|cffffcc00Action Bars disabled — type /reload to fully restore the default bars.|r"] = "|cffffcc00Панели команд отключены — введите /reload, чтобы полностью вернуть стандартные панели.|r",
    ["|cffaaaaaaTakes over every action bar with its own movable frame: real combat / mouseover show-hide, scale and grid layout per bar, correct main-bar paging (druid/rogue/warrior/priest forms) and your keybinds. EXPERIMENTAL: test ability clicks and form-switching in combat. After disabling, type /reload to fully restore Blizzard's bars.|r"] = "|cffaaaaaaБерет все панели команд под свое управление собственной перемещаемой рамкой: настоящий показ/скрытие в бою и при наведении, масштаб и сетка для каждой панели, правильное переключение страниц основной панели (формы друида/разбойника/воина/жреца) и ваши горячие клавиши. ЭКСПЕРИМЕНТАЛЬНО: проверьте нажатие способностей и смену форм в бою. После отключения введите /reload, чтобы полностью вернуть панели Blizzard.|r",
    ["Custom layout"] = "Свой макет",
    ["Arrange this bar's buttons in your own grid. Off keeps Blizzard's native layout."] = "Расставьте кнопки этой панели по собственной сетке. Выкл. сохраняет стандартный макет Blizzard.",
    ["Buttons per row"] = "Кнопок в ряду",
    ["Button spacing"] = "Расстояние между кнопками",
    ["World"] = "Мир",
    ["Crisp portrait hit numbers"] = "Четкие числа урона на портрете",
    ["Renders the damage/heal numbers that flash on the Player/Pet portrait with a fixed, sharp font instead of Blizzard's blurry growing animation."] = "Отображает числа урона/исцеления на портрете персонажа или питомца четким шрифтом фиксированного размера вместо размытой растущей анимации Blizzard.",
    ["Hit number size"] = "Размер чисел урона",
    ["Font size of the portrait hit numbers (when 'Crisp' is on)."] = "Размер шрифта чисел на портрете (при включенной опции «Четкие»).",
    ["Auto-select single gossip option"] = "Автовыбор единственного варианта диалога",
    ["Skips NPC dialog windows that only have a single option. Hold SHIFT to temporarily bypass."] = "Пропускает окна диалога с NPC, в которых есть лишь один вариант ответа. Удерживайте SHIFT, чтобы временно отключить.",
    ["Faster auto-loot"] = "Быстрый автосбор добычи",
    ["Loots all items at once when auto-loot applies, instead of one by one."] = "Собирает все предметы разом при автосборе добычи, а не по одному.",
    ["Max camera zoom"] = "Максимальное отдаление камеры",
    ["Raises the maximum camera zoom-out distance far beyond the default."] = "Увеличивает максимальное расстояние отдаления камеры далеко за пределы стандартного.",
    ["Player & Target Frame"] = "Рамка игрока и цели",
    ["Target & Focus Frame"] = "Рамка цели и фокуса",
    ["|cffaaaaaaPuts the golden elite dragon (or the rare variants) around your player portrait — the look elite mobs have on the target frame.|r"] = "|cffaaaaaaДобавляет золотого элитного дракона (или редкие варианты) вокруг портрета вашего персонажа — так выглядят элитные существа в рамке цели.|r",
    ["Frame style"] = "Стиль рамки",
    ["Elite (golden dragon)"] = "Элитный (золотой дракон)",
    ["Rare-Elite (silver dragon)"] = "Редкий элитный (серебряный дракон)",
    ["Rare (silver)"] = "Редкий (серебряный)",
    ["Off (default frame)"] = "Выкл. (обычная рамка)",
    ["Cooldown Manager"] = "Менеджер восстановления",
    ["A row of icons that shows the cooldowns of spells and trinkets you choose — like the retail cooldown manager."] = "Ряд значков, показывающий восстановление выбранных вами заклинаний и аксессуаров — как менеджер восстановления в актуальной версии игры.",
    ["Movable cooldown bars grouped however you like (procs, defensives, offensives ...) — like the retail cooldown manager."] = "Перемещаемые панели восстановления, сгруппированные как вам удобно (срабатывания, защитные, атакующие ...) — как менеджер восстановления в актуальной версии игры.",
    ["|cffaaaaaaMovable cooldown bars grouped however you like — e.g. one for procs/buffs, one for defensive cooldowns, one for offensives. Pick or create a group below, then add spells/trinkets to it.|r"] = "|cffaaaaaaПеремещаемые панели восстановления, сгруппированные как вам удобно — например, одна для срабатываний и эффектов, одна для защитных умений, одна для атакующих. Выберите или создайте группу ниже, затем добавьте в нее заклинания и аксессуары.|r",
    ["Cooldowns"] = "Восстановления",
    ["Groups"] = "Группы",
    ["Edit group"] = "Изменить группу",
    ["New group"] = "Новая группа",
    ["Group %d"] = "Группа %d",
    ["Delete group"] = "Удалить группу",
    ["|cff888888Nothing in this group yet.|r"] = "|cff888888В этой группе пока пусто.|r",
    ["Cooldown group '%s' unlocked. Drag spells/items onto it; |cff9b6cffdrag|r to move."] = "Группа восстановления «%s» разблокирована. Перетаскивайте на нее заклинания и предметы; |cff9b6cffперетащите|r, чтобы переместить.",
    ["Cooldown group '%s' locked."] = "Группа восстановления «%s» заблокирована.",
    ["Group type"] = "Тип группы",
    ["Buffs & Procs (only show while active)"] = "Эффекты и срабатывания (показывать только активные)",
    ["|cffaaaaaaIcons appear only while their buff/proc is on you; the bar is empty otherwise. Add the BUFF (e.g. Clearcasting) by name or ID.|r"] = "|cffaaaaaaЗначки появляются, только пока на вас действует эффект или срабатывание; в остальное время панель пуста. Добавляйте ЭФФЕКТ (например, «Ясновидение») по названию или ID.|r",
    ["|cffaaaaaaIcons show the cooldown of each spell/trinket.|r"] = "|cffaaaaaaЗначки показывают восстановление каждого заклинания или аксессуара.|r",
    ["Size & offsets"] = "Размер и смещения",
    ["Extra settings"] = "Дополнительные настройки",
    ["Friends List"] = "Список друзей",
    ["Class-coloured friend names, class icons, faction accent and optional auto-accept for Battle.net invites."] = "Имена друзей в цветах класса, значки классов, акцент фракции и необязательный автоприем приглашений Battle.net.",
    ["Dialog Popups"] = "Диалоговые окна",
    ["Restyles Blizzard's confirmation dialogs (logout countdown, delete item, resurrect, group invite) to match the dark look."] = "Оформляет стандартные диалоги подтверждения Blizzard (отсчет выхода из игры, удаление предмета, воскрешение, приглашение в группу) в темном стиле.",
    ["|cffaaaaaaRestyles Blizzard's confirmation dialogs — logout countdown, delete item, resurrect, group invite — to match the dark look.|r"] = "|cffaaaaaaОформляет стандартные диалоги подтверждения Blizzard — отсчет выхода из игры, удаление предмета, воскрешение, приглашение в группу — в темном стиле.|r",
    ["Accent strip"] = "Акцентная полоса",
    ["Draws a thin accent gradient along the top edge of each dialog."] = "Рисует тонкий акцентный градиент вдоль верхнего края каждого диалога.",
    ["Addon Skins"] = "Оформление аддонов",
    ["Restyles supported third-party addon windows to match the dark look: error list, quest tracker, loot browser, profiler and more."] = "Оформляет окна поддерживаемых сторонних аддонов в темном стиле: список ошибок, отслеживание заданий, обзор добычи, профилировщик и другое.",
    ["|cffaaaaaaRestyles the windows of supported addons to the dark look. Skins apply when the addon is loaded; turning one off needs a /reload (the quest tracker restores live).|r"] = "|cffaaaaaaОформляет окна поддерживаемых аддонов в темном стиле. Оформление применяется при загрузке аддона; для отключения нужен /reload (отслеживание заданий восстанавливается сразу).|r",
    ["not loaded"] = "не загружен",
    ["Map addon"] = "Аддон карты",
    ["Dark window skin"] = "Темное оформление окна",
    ["Restyles the whole friends window dark with purple accents. Turning it off needs a /reload to restore Blizzard's frame."] = "Оформляет все окно друзей в темных тонах с фиолетовыми акцентами. Для отключения нужен /reload, чтобы вернуть стандартную рамку Blizzard.",
    ["Class color names"] = "Имена в цветах класса",
    ["Colors each online friend's name by their class."] = "Окрашивает имя каждого друга в сети в цвет его класса.",
    ["Show class icons"] = "Показывать значки классов",
    ["Shows a class icon next to online WoW friends (in-game and Battle.net)."] = "Показывает значок класса рядом с друзьями в WoW, находящимися в сети (в игре и в Battle.net).",
    ["Class icon style"] = "Стиль значков классов",
    ["Blizzard crests"] = "Гербы Blizzard",
    ["Vulo Modern"] = "Vulo Modern",
    ["Vulo Style"] = "Vulo Style",
    ["Vulo icons"] = "Значки Vulo",
    ["Circles"] = "Круги",
    ["Squares"] = "Квадраты",
    ["Show status dot"] = "Показывать точку статуса",
    ["A coloured dot after the name: green online, yellow away, red busy, grey offline."] = "Цветная точка после имени: зеленая — в сети, желтая — отошел, красная — занят, серая — не в сети.",
    ["Show friend notes"] = "Показывать заметки о друзьях",
    ["Shows your saved note for the friend in grey under their name."] = "Показывает сохраненную заметку о друге серым цветом под его именем.",
    ["Faction"] = "Фракция",
    ["Faction accent on realm line"] = "Акцент фракции в строке игрового мира",
    ["Tints the realm/zone line red (Horde) or blue (Alliance)."] = "Окрашивает строку игрового мира и зоны в красный (Орда) или синий (Альянс) цвет.",
    ["Faction row tint"] = "Подсветка строки по фракции",
    ["Adds a subtle red/blue background tint to each online friend's row."] = "Добавляет легкую красную или синюю подсветку фона в строке каждого друга в сети.",
    ["Invites"] = "Приглашения",
    ["Auto-accept Battle.net friend invites"] = "Автоприем заявок в друзья Battle.net",
    ["Automatically accepts incoming Battle.net friend requests."] = "Автоматически принимает входящие заявки в друзья Battle.net.",
    ["Auto-accept group invites from friends"] = "Автоприем приглашений в группу от друзей",
    ["Automatically joins a group when the invite comes from someone on your friends list."] = "Автоматически принимает вступление в группу, если приглашение пришло от игрока из вашего списка друзей.",
    ["Class-coloured names, class icons, status dots, inline notes, faction tint and optional auto-accept."] = "Имена в цветах класса, значки классов, точки статуса, встроенные заметки, подсветка фракции и необязательный автоприем.",
    ["Highlight"] = "Подсветка",
    ["Proc glow (animated)"] = "Свечение срабатывания (анимированное)",
    ["Glow"] = "Свечение",
    ["Colored border"] = "Цветное обрамление",
    ["Highlight color"] = "Цвет подсветки",
    ["Yellow"] = "Желтый",
    ["Purple"] = "Фиолетовый",
    ["White"] = "Белый",
    ["|cffaaaaaaA row of icons showing the cooldowns of the spells and trinkets you add. Type a spell/item name or ID below, shift-click a spell from your spellbook into the box, or unlock the bar and drag spells/items onto it.|r"] = "|cffaaaaaaРяд значков, показывающий восстановление добавленных вами заклинаний и аксессуаров. Введите ниже название или ID заклинания либо предмета, перетащите заклинание из книги заклинаний в поле ввода по SHIFT+щелчку или разблокируйте панель и перетащите заклинания и предметы на нее.|r",
    ["Cooldown Manager: '%s' is not a known spell or item."] = "Менеджер восстановления: «%s» — неизвестное заклинание или предмет.",
    ["Cooldown Manager: already tracking that."] = "Менеджер восстановления: это уже отслеживается.",
    ["Cooldown Manager: added %s."] = "Менеджер восстановления: добавлено %s.",
    ["Bar scale"] = "Масштаб панели",
    ["Icon border thickness"] = "Толщина обрамления значка",
    ["Class-colored border"] = "Обрамление в цвете класса",
    ["Border color..."] = "Цвет обрамления...",
    ["Bar background"] = "Фон панели",
    ["Background color..."] = "Цвет фона...",
    ["Show this bar"] = "Показывать эту панель",
    ["Only in a party (not raid)"] = "Только в группе (не в рейде)",
    ["Only in a raid"] = "Только в рейде",
    ["Only while solo"] = "Только в одиночку",
    ["Never (temporarily off)"] = "Никогда (временно выкл.)",
    ["Countdown text size"] = "Размер текста отсчета",
    ["Percent of the icon size."] = "Процент от размера значка.",
    ["Countdown text color..."] = "Цвет текста отсчета...",
    ["Warn color under (sec)"] = "Цвет предупреждения ниже (сек.)",
    ["Below this many seconds the countdown switches to the warn color; 0 turns the warn color off."] = "Ниже этого числа секунд отсчет переключается на цвет предупреждения; 0 отключает цвет предупреждения.",
    ["Warn color..."] = "Цвет предупреждения...",
    ["Glow while ready"] = "Свечение при готовности",
    ["A steady glow while the cooldown is ready - and, for spells, only while it is actually usable (enough mana etc.)."] = "Постоянное свечение, пока восстановление завершено — и для заклинаний только тогда, когда его действительно можно применить (хватает маны и т. п.).",
    ["Glow color"] = "Цвет свечения",
    ["Show keybinds"] = "Показывать горячие клавиши",
    ["Shows the key the spell/item is bound to on your action bars. Macros are not matched; stance pages follow the main bar."] = "Показывает клавишу, на которую заклинание или предмет назначены на ваших панелях команд. Макросы не учитываются; страницы стоек следуют за основной панелью.",
    ["Keybind color..."] = "Цвет горячих клавиш...",
    ["Keep inactive buffs visible (greyed out)"] = "Оставлять неактивные эффекты видимыми (обесцвеченными)",
    ["Icons stay in place when the buff runs out, just desaturated - the bar never jumps around."] = "Значки остаются на месте, когда эффект заканчивается, просто обесцвечиваются — панель не прыгает.",
    ["Add (name / ID)"] = "Добавить (название / ID)",
    ["Tracked"] = "Отслеживается",
    ["|cff888888Nothing tracked yet.|r"] = "|cff888888Пока ничего не отслеживается.|r",
    ["  |cff888888(item)|r"] = "  |cff888888(предмет)|r",
    ["Up"] = "Вверх",
    ["Icons per row"] = "Значков в ряду",
    ["Growth direction"] = "Направление роста",
    ["Right"] = "Вправо",
    ["Left"] = "Влево",
    ["Down"] = "Вниз",
    ["Up (direction)"] = "Вверх (направление)",
    ["Only show while on cooldown"] = "Показывать только во время восстановления",
    ["Hides ready icons; they reappear when on cooldown."] = "Скрывает готовые значки; они появляются снова, когда умение уходит на восстановление.",
    ["Show countdown text"] = "Показывать текст отсчета",
    ["Show stacks"] = "Показывать стопки",
    ["  |cffaa5555(other class)|r"] = "  |cffaa5555(другой класс)|r",
    ["Unlock Mode"] = "Режим разблокировки",
    ["|cffaaaaaaFor Blizzard's own Edit Mode: open it yourself via the game menu (|cffffffffEsc → Edit Mode|r). Blizzard blocks addons from starting it. Once it's open, your VuloUI windows appear in it automatically.|r"] = "|cffaaaaaaДля стандартного Режима редактирования Blizzard: откройте его сами через игровое меню (|cffffffffEsc → Режим редактирования|r). Blizzard запрещает аддонам запускать его. Как только он открыт, окна VuloUI появляются в нем автоматически.|r",
    ["Open Blizzard's Edit Mode"] = "Открыть Режим редактирования Blizzard",
    ["Open game menu for Blizzard's Edit Mode"] = "Открыть игровое меню для Режима редактирования Blizzard",
    ["Blizzard blocks addons from starting Edit Mode directly (it would taint). This opens the game menu — pick 'Edit Mode' there. Our windows then appear in it automatically."] = "Blizzard запрещает аддонам напрямую запускать Режим редактирования (это нарушило бы защищенный код). Эта кнопка открывает игровое меню — выберите там «Режим редактирования». Наши окна затем появятся в нем автоматически.",
    ["Opens Blizzard's own Edit Mode (closes this window first). Our windows show up in it too."] = "Открывает стандартный Режим редактирования Blizzard (сначала закрывает это окно). Наши окна тоже отображаются в нем.",
    ["Can't open Edit Mode in combat."] = "Нельзя открыть Режим редактирования в бою.",
    ["This client has no Blizzard Edit Mode."] = "В этом клиенте нет Режима редактирования Blizzard.",
    ["Activate edit mode to move every VuloUI window at once."] = "Включите режим редактирования, чтобы перемещать все окна VuloUI сразу.",
    ["|cffaaaaaaActivate edit mode to move every VuloUI window at once — cooldown bars, combat text, trackers, castbar, swing timer and more. It also opens automatically with Blizzard's Edit Mode.|r"] = "|cffaaaaaaВключите режим редактирования, чтобы перемещать все окна VuloUI сразу — панели восстановления, боевой текст, трекеры, полосу заклинания, таймер удара и другое. Он также открывается автоматически вместе с Режимом редактирования Blizzard.|r",
    ["|cff888888• Drag a purple box to move that window.|n• Hover a box, then use the arrow keys to fine-tune (SHIFT = 5px).|n• Right-click a box for exact X / Y.|n• |cffffffff/cdedit|r toggles this too.|r"] = "|cff888888• Перетащите фиолетовый блок, чтобы переместить это окно.|n• Наведите курсор на блок и используйте стрелки для точной настройки (SHIFT = 5 пикс.).|n• Щелкните по блоку правой кнопкой для точных X / Y.|n• |cffffffff/cdedit|r также переключает этот режим.|r",
    ["|cff44ff44Edit mode is ON.|r Close this window to reach the boxes, then lock again here or with /cdedit."] = "|cff44ff44Режим редактирования ВКЛ.|r Закройте это окно, чтобы добраться до блоков, затем снова заблокируйте здесь или командой /cdedit.",
    ["Edit mode — move the cooldown bars"] = "Режим редактирования — перемещение панелей восстановления",
    ["Stop editing — lock the cooldown bars"] = "Завершить редактирование — заблокировать панели восстановления",
    ["Unlocks just the cooldown bars so you can drag them. Arrow keys fine-tune; right-click a purple box for X/Y. (To move ALL VuloUI windows, use 'Unlock Mode' in Global.)"] = "Разблокирует только панели восстановления, чтобы их можно было перетаскивать. Стрелки — точная настройка; щелчок правой кнопкой по фиолетовому блоку задает X/Y. (Чтобы перемещать ВСЕ окна VuloUI, используйте «Режим разблокировки» в разделе «Общее».)",
    ["Edit mode — move all VuloUI windows"] = "Режим редактирования — перемещение всех окон VuloUI",
    ["Stop editing — lock all windows"] = "Завершить редактирование — заблокировать все окна",
    ["Unlocks every movable VuloUI window at once (cooldown bars, combat text, trackers …) so you can drag them. Arrow keys fine-tune; right-click a purple box for X/Y. Also opens with Blizzard's Edit Mode."] = "Разблокирует все перемещаемые окна VuloUI сразу (панели восстановления, боевой текст, трекеры …), чтобы их можно было перетаскивать. Стрелки — точная настройка; щелчок правой кнопкой по фиолетовому блоку задает X/Y. Также открывается вместе с Режимом редактирования Blizzard.",
    ["right-click: settings"] = "щелчок правой кнопкой: настройки",
    ["Edit mode — unlock all bars to move"] = "Режим редактирования — разблокировать все панели для перемещения",
    ["Stop editing — lock all bars"] = "Завершить редактирование — заблокировать все панели",
    ["Unlocks every cooldown bar at once so you can drag them all into place. Also opens automatically with Blizzard's Edit Mode. Anchoring is set per group in 'Anchor'."] = "Разблокирует все панели восстановления сразу, чтобы расставить их по местам. Также открывается автоматически вместе с Режимом редактирования Blizzard. Привязка настраивается отдельно для каждой группы в разделе «Привязка».",
    ["Cooldown edit mode |cff44ff44ON|r — drag any bar to move it. Toggle again to lock."] = "Режим редактирования восстановлений |cff44ff44ВКЛ|r — перетащите любую панель, чтобы переместить ее. Нажмите снова, чтобы заблокировать.",
    ["Cooldown edit mode |cffff5555OFF|r — all bars locked."] = "Режим редактирования восстановлений |cffff5555ВЫКЛ|r — все панели заблокированы.",
    ["Hide cooldowns under (sec)"] = "Скрывать восстановления короче (сек.)",
    ["Cooldowns at or below this are ignored. 1.5 hides the global cooldown; raise it to also hide short cooldowns; 0 shows everything."] = "Восстановления с этим значением и меньше игнорируются. 1.5 скрывает общее восстановление; увеличьте, чтобы скрывать и короткие восстановления; 0 показывает все.",
    ["Reorder / remove"] = "Порядок / удаление",
    ["Move earlier"] = "Переместить раньше",
    ["Move later"] = "Переместить позже",
    ["Stack / reagent position"] = "Положение стопок / реагентов",
    ["Stack / reagent size"] = "Размер стопок / реагентов",
    ["Stack / reagent color..."] = "Цвет стопок / реагентов...",
    ["Bottom right"] = "Снизу справа",
    ["Bottom left"] = "Снизу слева",
    ["Top right"] = "Сверху справа",
    ["Top left"] = "Сверху слева",
    ["Show reagent counts"] = "Показывать количество реагентов",
    ["Shows each spell's OWN reagent count — Soul Shards on Soul Fire, Infernal Stone on Inferno, etc. Spells without a reagent show nothing. Needs 'Show stacks' on."] = "Показывает СОБСТВЕННОЕ количество реагентов каждого заклинания — осколки душ у «Огня Скверны», камень инфернала у «Инфернала» и т. д. Заклинания без реагентов не показывают ничего. Требует включенной опции «Показывать стопки».",
    ["Anchor"] = "Привязка",
    ["Anchor to"] = "Привязать к",
    ["Pin this bar to a unit frame, the minimap, or another group's bar — it then moves with it. Drag the bar to detach."] = "Прикрепите эту панель к рамке существа, миникарте или панели другой группы — тогда она будет перемещаться вместе с ней. Перетащите панель, чтобы открепить.",
    ["Player Frame"] = "Рамка игрока",
    ["Focus Frame"] = "Рамка фокуса",
    ["Pet Frame"] = "Рамка питомца",
    ["None (free)"] = "Нет (свободно)",
    ["Cooldown Manager: can't anchor there — it would loop."] = "Менеджер восстановления: сюда привязать нельзя — получится замкнутый круг.",
    ["Side"] = "Сторона",
    ["Below"] = "Снизу",
    ["Above"] = "Сверху",
    ["Left of"] = "Слева",
    ["Right of"] = "Справа",
    ["X offset"] = "Смещение по X",
    ["Y offset"] = "Смещение по Y",
    ["Icon shape"] = "Форма значка",
    ["Square"] = "Квадрат",
    ["Rounded"] = "Скругленная",
    ["Icon zoom"] = "Приближение значка",
    ["Cooldown swipe darkness"] = "Затемнение маски восстановления",
    ["Only in combat"] = "Только в бою",
    ["Only with a target"] = "Только при наличии цели",
    ["Only with an attackable target"] = "Только при враждебной цели",
    ["Hide while mounted"] = "Скрывать верхом",
    ["Only in instances"] = "Только в подземельях",
    ["Dim icon while on cooldown"] = "Затемнять значок во время восстановления",
    ["Flash when ready"] = "Вспышка при готовности",
    ["|cffffffffCOOLDOWNS|r"] = "|cffffffffВОССТАНОВЛЕНИЯ|r",
    ["Cooldowns: x=%.0f, y=%.0f"] = "Восстановления: x=%.0f, y=%.0f",
    ["Cooldown Manager unlocked. Drag spells/items onto the bar to add. |cff9b6cffDrag|r the bar to move."] = "Менеджер восстановления разблокирован. Перетаскивайте заклинания и предметы на панель, чтобы добавить их. |cff9b6cffПеретащите|r панель, чтобы переместить.",
    ["Cooldown Manager locked."] = "Менеджер восстановления заблокирован.",
    ["Saves named snapshots of your action bars, macros and keybindings, and restores them with one click."] = "Сохраняет именованные снимки ваших панелей команд, макросов и назначений клавиш и восстанавливает их одним щелчком.",
    ["|cffaaaaaaSaves your complete bar setup (all action slots, macros, keybindings) as a named profile and restores it with one click — e.g. PvP and Raid layouts, or to copy a setup to a twink (account-wide storage).|r"] = "|cffaaaaaaСохраняет всю настройку панелей (все ячейки команд, макросы, назначения клавиш) как именованный профиль и восстанавливает ее одним щелчком — например, макеты для PvP и рейда или перенос настройки на твинка (хранение для всей учетной записи).|r",
    ["Load"] = "Загрузить",
    ["Save current setup"] = "Сохранить текущую настройку",
    ["Please enter a profile name first."] = "Сначала введите название профиля.",
    ["|cff888888No profiles saved yet.|r"] = "|cff888888Профили пока не сохранены.|r",
    ["Also restore macros"] = "Восстанавливать также макросы",
    ["Rewrites saved macros by name (existing ones are updated, missing ones created)."] = "Перезаписывает сохраненные макросы по названию (существующие обновляются, отсутствующие создаются).",
    ["Also restore keybindings"] = "Восстанавливать также назначения клавиш",
    ["Load profile"] = "Загрузить профиль",
    ["Overwrite with current setup"] = "Перезаписать текущей настройкой",
    ["Replaces the selected profile with your current bars/macros/bindings."] = "Заменяет выбранный профиль вашими текущими панелями, макросами и назначениями клавиш.",
    ["Note: profile '%s' was saved on another class (%s)."] = "Внимание: профиль «%s» был сохранен на другом классе (%s).",
    ["Flight Timer"] = "Таймер полета",
    ["|cffff8800Flight route database not loaded.|r Fully restart WoW (a /reload is not enough after an update) so the flight times work."] = "|cffff8800База маршрутов полетов не загружена.|r Полностью перезапустите WoW (после обновления /reload недостаточно), чтобы время полета работало.",
    ["Show flight time bar"] = "Показывать полосу времени полета",
    ["Shows destination and remaining time while on a taxi. The first flight of a route is learned, then you get a draining countdown."] = "Показывает пункт назначения и оставшееся время во время полета. Первый полет по маршруту запоминается, затем вы получаете убывающий отсчет.",
    ["Shows a progress bar with the duration of taxi flights. Unknown routes are learned on the first flight."] = "Показывает полосу выполнения с длительностью полетов. Неизвестные маршруты запоминаются при первом полете.",
    ["|cffaaaaaaShows a bar with destination and remaining time while on a taxi. The first flight of a route counts up and is saved; from then on you get a countdown.|r"] = "|cffaaaaaaПоказывает полосу с пунктом назначения и оставшимся временем во время полета. Первый полет по маршруту отсчитывается вверх и сохраняется; в дальнейшем вы получаете обратный отсчет.|r",
    ["(learning)"] = "(запоминание)",
    ["Flight: %s (%s)"] = "Полет: %s (%s)",
    ["Print flight time to chat"] = "Выводить время полета в чат",
    ["After landing, prints the measured flight time."] = "После приземления выводит измеренное время полета.",
    ["Reset learned times"] = "Сбросить запомненное время",
    ["Deletes all saved route durations."] = "Удаляет всю сохраненную длительность маршрутов.",
    ["Learned flight times reset."] = "Запомненное время полетов сброшено.",
    ["|cffaaaaaaLearned routes: %d|r"] = "|cffaaaaaaЗапомнено маршрутов: %d|r",
    ["|cffffffffFLIGHT TIME|r"] = "|cffffffffВРЕМЯ ПОЛЕТА|r",
    ["Flight timer: x=%.0f, y=%.0f"] = "Таймер полета: x=%.0f, y=%.0f",
    ["Flight timer mover active. |cff9b6cffDrag|r or |cff9b6cffarrow keys|r (SHIFT = 5px)."] = "Перемещение таймера полета включено. |cff9b6cffПеретащите|r или используйте |cff9b6cffстрелки|r (SHIFT = 5 пикс.).",
    ["Flight timer mover disabled."] = "Перемещение таймера полета выключено.",
    ["Flight debug on — take a flight, the resolution appears in the chat."] = "Отладка полетов включена — совершите перелет, разбор появится в чате.",
    ["Flight debug off."] = "Отладка полетов выключена.",
    ["LazyVulo"] = "LazyVulo",
    ["VulTraining"] = "VulTraining",
    ["Group Board"] = "Доска групп",
    ["Apexis Relic memory minigame helper (Ogri'la dailies): record the flashing color sequence, always see what to click next."] = "Помощник для мини-игры на память с апекситовой реликвией (ежедневные задания Огри'лы): записывайте мигающую последовательность цветов и всегда видьте, куда нажать дальше.",
    ["Green relic"] = "Зеленая реликвия",
    ["Yellow relic"] = "Желтая реликвия",
    ["Blue relic"] = "Синяя реликвия",
    ["Red relic"] = "Красная реликвия",
    ["Left click: remove this entry.\nRight click: remove this and all later entries."] = "Щелчок левой кнопкой: удалить эту запись.\\nЩелчок правой кнопкой: удалить эту и все последующие записи.",
    ["Click to record this color."] = "Нажмите, чтобы записать этот цвет.",
    ["Hotkey: %s"] = "Горячая клавиша: %s",
    ["LazyVulo is disabled."] = "LazyVulo отключен.",
    ["|cffaaaaaaHelper for the Apexis Relic memory minigame (Ogri'la dailies). Record the flashing sequence with the buttons or hotkeys; the first icon is always your next click. Correct clicks are consumed automatically, wrong clicks are restored.|r"] = "|cffaaaaaaПомощник для мини-игры на память с апекситовой реликвией (ежедневные задания Огри'лы). Записывайте мигающую последовательность кнопками или горячими клавишами; первый значок — всегда ваш следующий щелчок. Верные щелчки убираются автоматически, ошибочные восстанавливаются.|r",
    ["|cffaaaaaaOpen manually with /lazyvulo or /lv.|r"] = "|cffaaaaaaОткрывается вручную командой /lazyvulo или /lv.|r",
    ["Auto-show at the Apexis Relic"] = "Автопоказ у апекситовой реликвии",
    ["Opens the window automatically when you start the relic minigame."] = "Автоматически открывает окно, когда вы начинаете мини-игру с реликвией.",
