    ["You gave"] = "Вы передали",
    ["gave you"] = "передал вам",
    ["reflected"] = "отразил",
    ["Purged (enemy buff removed)"] = "Снято (эффект врага удален)",
    ["Dispelled (by you)"] = "Рассеяно (вами)",
    ["Dispelled (your buff lost)"] = "Рассеяно (ваш эффект снят)",
    ["Buff given"] = "Эффект передан",
    ["Buff received"] = "Эффект получен",
    ["Reflected"] = "Отражено",
    ["Show spell icons"] = "Показывать значки заклинаний",
    ["Party member died"] = "Погиб член группы",
    ["%s died"] = "%s погиб",
    ["Shows the spell icon inline next to the spell name."] = "Показывает значок заклинания рядом с его названием.",
    ["Parried"] = "Парирование",
    ["Dodged"] = "Уклонение",
    ["Missed"] = "Промах",
    ["Blocked"] = "Блокирование",
    ["Absorbed"] = "Поглощение",
    ["|cffffffffCOMBAT TEXT|r"] = "|cffffffffБОЕВОЙ ТЕКСТ|r",
    ["Combat Text mover active. Drag or arrow keys (SHIFT=5px)."] = "Перемещение боевого текста включено. Перетаскивание или стрелки (SHIFT=5 пикс.).",
    ["|cffaaaaaaCustom scrolling text engine above the player. Anniversary disabled Blizzard's old player FCT. Each event can have its own color + size + outline/shadow.|r"] = "|cffaaaaaaСобственный движок прокручиваемого текста над персонажем. В Anniversary отключен старый всплывающий боевой текст Blizzard для игрока. У каждого события может быть свой цвет, размер и контур/тень.|r",
    ["Flashing combat notifications (with live preview) plus a scrolling combat-log text engine."] = "Мигающие боевые оповещения (с живым предпросмотром) и движок прокручиваемого текста боевого журнала.",
    ["|cffaaaaaaNotifications (+/- Combat, Low Durability) flash centred and stack; combat-log events (interrupts, dispels, misses) scroll upward. Use Preview to position and style them.|r"] = "|cffaaaaaaОповещения (+/- Бой, низкая прочность) мигают по центру и складываются в стопку; события боевого журнала (прерывания, рассеивания, промахи) прокручиваются вверх. Используйте предпросмотр, чтобы разместить и оформить их.|r",
    ["Show Preview"] = "Показать предпросмотр",
    ["Shows all three notification messages on screen so you can position and style them. Turns off automatically when you close this window."] = "Показывает на экране все три оповещения, чтобы вы могли разместить и оформить их. Автоматически выключается при закрытии этого окна.",
    ["Notifications (flash & stack)"] = "Оповещения (мигание и стопка)",
    ["Combat Log (scrolling)"] = "Боевой журнал (прокрутка)",
    ["Text"] = "Текст",
    ["Outline Style"] = "Стиль контура",
    ["Thick Outline"] = "Толстый контур",
    ["Flash Duration (sec.)"] = "Длительность мигания (сек.)",
    ["How long the +/- Combat flash stays before fading."] = "Сколько держится вспышка +/- Бой перед затуханием.",
    ["Categories (Quick on/off)"] = "Категории (быстрое вкл./выкл.)",
    ["Combat State (+/- Combat)"] = "Состояние боя (+/- Бой)",
    ["Combat start and combat end messages."] = "Сообщения о начале и конце боя.",
    ["Combat Log Events"] = "События боевого журнала",
    ["Interrupts, dispels, misses (Parry/Dodge/Block)."] = "Прерывания, рассеивания, промахи (парирование/уклонение/блокирование).",
    ["Durability Warning"] = "Предупреждение о прочности",
    ["Low durability after combat exit."] = "Низкая прочность после выхода из боя.",
    ["Global Defaults"] = "Общие значения по умолчанию",
    ["Per-Event Customization"] = "Настройка по событиям",
    ["Font for our combat text engine. Also used for Blizzard's mob FCT (DAMAGE_TEXT_FONT) when enabled below."] = "Шрифт нашего движка боевого текста. Также используется для боевого текста Blizzard над существами (DAMAGE_TEXT_FONT), если включено ниже.",
    ["Also apply font to Blizzard mob FCT"] = "Применять шрифт и к боевому тексту Blizzard над существами",
    ["Additionally sets DAMAGE_TEXT_FONT globally - changes the font of the damage numbers above mobs/pets. Requires /reload to take effect."] = "Дополнительно задает DAMAGE_TEXT_FONT глобально — меняет шрифт чисел урона над существами и питомцами. Требуется /reload.",
    ["Default: Thick Outline"] = "По умолчанию: толстый контур",
    ["Default: Shadow"] = "По умолчанию: тень",
    ["Scroll Duration (sec.)"] = "Длительность прокрутки (сек.)",
    ["Scroll Distance (px)"] = "Расстояние прокрутки (пикс.)",
    ["Interrupted"] = "Прервано",
    ["Interrupted: Frostbolt"] = "Прервано: Ледяная стрела",
    ["Dispelled/Purged"] = "Рассеяно/Снято",
    ["Dispelled: Curse"] = "Рассеяно: Проклятие",
    ["Parried/Dodged/Missed"] = "Парирование/уклонение/промах",
    ["Low Durability"] = "Низкая прочность",
    ["Durability Threshold (%)"] = "Порог прочности (%)",
    ["Warning appears when at least one equipped item is below this value (after combat exit)."] = "Предупреждение появляется, когда хотя бы один надетый предмет опускается ниже этого значения (после выхода из боя).",
    ["Engine FCT (above mob/pet)"] = "Боевой текст движка (над существом/питомцем)",
    ["Sharper hit indicator font (Friz Quadrata)"] = "Более четкий шрифт чисел урона (Friz Quadrata)",
    ["Engine FCT Scale"] = "Масштаб боевого текста движка",
    ["Damage numbers above mob/pet — bitmap scaling."] = "Числа урона над существом/питомцем — масштабирование растрового шрифта.",
    ["Center"] = "Центрировать",
    ["Keeps the horizontal position and only centers vertically in the screen center."] = "Сохраняет положение по горизонтали и центрирует только по вертикали относительно центра экрана.",
    ["Unlock / Position"] = "Разблокировать / положение",
    ["Trinkets"] = "Аксессуары",
    ["Two trinket slots on screen with cooldown display, dropdown selection and auto-queue."] = "Два слота аксессуаров на экране с показом восстановления, выпадающим выбором и автоочередью.",
    ["|cffaaaaaaTwo trinket slots with cooldown, dropdown selection and auto-queue.|nLeft click = use, right click = dropdown.|r"] = "|cffaaaaaaДва слота аксессуаров с восстановлением, выпадающим выбором и автоочередью.|nЛевый щелчок — использовать, правый — выпадающий список.|r",
    ["Show frame"] = "Показывать рамку",
    ["Hides or shows the two trinket slots. Auto-queue continues to run while hidden."] = "Скрывает или показывает два слота аксессуаров. Автоочередь продолжает работать, даже когда рамка скрыта.",
    ["Position locked"] = "Положение закреплено",
    ["If on, the frame cannot be accidentally moved."] = "Если включено, рамку нельзя случайно сдвинуть.",
    ["Size"] = "Размер",
    ["Scales the trinket slots."] = "Масштабирует слоты аксессуаров.",
    ["|cffaaaaaaTip: Left click on a slot uses the trinket, right click shows the selection list. Auto-queue is configured via right click -> Queue tab.|r"] = "|cffaaaaaaСовет: левый щелчок по слоту использует аксессуар, правый показывает список выбора. Автоочередь настраивается через правый щелчок → вкладка «Очередь».|r",
    ["Character Panel"] = "Панель персонажа",
    ["Dark Skin"] = "Темное оформление",
    ["The dark look of the UI in one place: a built-in dark skin for action buttons and WeakAuras icons, plus an optional Dark Mode that darkens Blizzard's default frames, minimap and bars."] = "Темный вид интерфейса в одном месте: встроенное темное оформление кнопок команд и значков WeakAuras, плюс необязательный темный режим, затемняющий стандартные рамки, миникарту и панели Blizzard.",
    ["|cffaaaaaaThe dark look of the UI in one place: a built-in skin for action buttons and WeakAuras icons, plus an optional Dark Mode that re-tints Blizzard's default frames.|r"] = "|cffaaaaaaТемный вид интерфейса в одном месте: встроенное оформление кнопок команд и значков WeakAuras, плюс необязательный темный режим, перекрашивающий стандартные рамки Blizzard.|r",
    ["The dark action-bar button skin."] = "Темное оформление кнопок панели команд.",
    ["Enable Dark Mode"] = "Включить темный режим",
    ["Re-tints Blizzard's default frames, minimap and action-bar artwork to a dark tone. Off by default."] = "Перекрашивает стандартные рамки, миникарту и графику панелей команд Blizzard в темный тон. По умолчанию выключено.",
    ["|cffaaaaaaOptional: darkens and desaturates Blizzard's default artwork — unit frames, minimap and action bars — to a neutral dark tone. Reversible: turn it off and the gold look returns.|r"] = "|cffaaaaaaНеобязательно: затемняет и обесцвечивает стандартную графику Blizzard — рамки существ, миникарту и панели команд — до нейтрального темного тона. Обратимо: выключите, и золотой вид вернется.|r",
    ["Button Skin"] = "Оформление кнопок",
    ["Built-in dark drop-shadow skin for action buttons and WeakAuras icons: black, rounded, soft rim. Several styles, no extra addons needed."] = "Встроенное темное оформление с тенью для кнопок команд и значков WeakAuras: черное, скругленное, с мягкой каймой. Несколько стилей, дополнительные аддоны не нужны.",
    ["|cffaaaaaaBuilt-in dark drop-shadow skin. Action bars and WeakAuras icons are configured separately below.|r"] = "|cffaaaaaaВстроенное темное оформление с тенью. Панели команд и значки WeakAuras настраиваются отдельно ниже.|r",
    ["Action Bars"] = "Панели команд",
    ["Skin the action bars"] = "Оформлять панели команд",
    ["The dark action-bar border. Works on its own, and Dark Mode can drive it too."] = "Темная кайма панели команд. Работает сама по себе, и темный режим тоже может ее включать.",
    ["Bar style"] = "Стиль панели",
    ["Bar icon size"] = "Размер значка на панели",
    ["How much of the button the icon fills in Shadow style. Higher = bigger icons with a thinner rim."] = "Насколько значок заполняет кнопку в стиле «Тень». Больше — крупнее значки и тоньше кайма.",
    ["WeakAuras Icons"] = "Значки WeakAuras",
    ["Skin WeakAuras icons"] = "Оформлять значки WeakAuras",
    ["WeakAuras style"] = "Стиль WeakAuras",
    ["Style for WeakAuras icons, independent of the action bars."] = "Стиль значков WeakAuras, независимо от панелей команд.",
    ["Hide WeakAuras' own border"] = "Скрыть собственную кайму WeakAuras",
    ["Hides the light border WeakAuras draws on icons, so only our dark rim shows. /reload to fully restore it."] = "Скрывает светлую кайму, которую WeakAuras рисует на значках, чтобы оставалась только наша темная. Для полного возврата нужен /reload.",
    ["Pick how the action buttons look. Rounded/Circle use an icon mask; Minimal is just the cropped icon."] = "Выберите вид кнопок команд. «Скругленный» и «Круг» используют маску значка; «Минимальный» — только обрезанный значок.",
    ["Shadow (dark rounded rim)"] = "Тень (темная скругленная кайма)",
    ["Rounded icon (masked corners)"] = "Скругленный значок (маска углов)",
    ["Square (black edge)"] = "Квадрат (черный край)",
    ["Square (accent edge)"] = "Квадрат (акцентный край)",
    ["Circle"] = "Круг",
    ["Minimal (icon only)"] = "Минимальный (только значок)",
    ["Minimal Dark (darkened Blizzard border)"] = "Минимальный темный (затемненная кайма Blizzard)",
    ["|cffaaaaaaNote: turning a skin off fully reverts after a /reload.|r"] = "|cffaaaaaaПримечание: выключение оформления полностью откатывается после /reload.|r",
    ["Also skin pet & stance buttons"] = "Оформлять также кнопки питомца и стоек",
    ["Enhances the character panel: iLvL per slot, socket display, shortened enchant text."] = "Улучшает панель персонажа: уровень предмета в каждой ячейке, показ гнезд, сокращенный текст чар.",
    ["Show item level per slot"] = "Показывать уровень предмета в каждой ячейке",
    ["Show average item level"] = "Показывать средний уровень предметов",
    ["Show sockets"] = "Показывать гнезда",
    ["Shorten enchant text (DE/EN)"] = "Сокращать текст чар (DE/EN)",
    ["Example: 'Stamina' -> 'Stam', 'Ausdauer' -> 'Ausd'."] = "Например: «Stamina» → «Stam», «Ausdauer» → «Ausd».",
    ["Treat rings as enchantable"] = "Считать кольца зачаровываемыми",
    ["Also shows enchant text on rings (TBC: some professions can enchant rings). /reload required."] = "Также показывает текст чар на кольцах (в TBC некоторые профессии могут зачаровывать кольца). Требуется /reload.",
    ["Text Size"] = "Размер текста",
    ["Item Level Text Size"] = "Размер текста уровня предмета",
    ["Font size of the item level number on each item slot. Takes effect immediately when the character panel is open."] = "Размер шрифта числа уровня предмета в каждой ячейке. Применяется сразу, если панель персонажа открыта.",
    ["Note: Some changes only take full effect after /reload, since the character panel is hooked on load."] = "Примечание: некоторые изменения полностью вступают в силу только после /reload, так как панель персонажа перехватывается при загрузке.",
    ["|cffff0000No Ench|r"] = "|cffff0000Без чар|r",
    ["|c%siLvL - %d|r"] = "|c%sУр.пред. - %d|r",
    ["Gold Tracker"] = "Учет золота",
    ["Shows in the backpack gold tooltip how much gold has been gained or spent since the last reset. Per-char persistent."] = "Показывает в подсказке золота рюкзака, сколько золота получено или потрачено с последнего сброса. Сохраняется отдельно для каждого персонажа.",
    ["Gold Tracker reset|r. Start = "] = "Учет золота сброшен|r. Начало = ",
    ["Gold Balance|r"] = "Баланс золота|r",
    ["Gained:|r"] = "Получено:|r",
    ["Spent:|r"] = "Потрачено:|r",
    ["|cffffffffNet:|r"] = "|cffffffffИтого:|r",
    ["Start:|r"] = "Начало:|r",
    ["Now:|r"] = "Сейчас:|r",
    ["Reset with /vcui goldreset|r"] = "Сброс командой /vcui goldreset|r",
    ["|cffaaaaaaShows in the backpack gold tooltip the balance since the last manual reset:|n  - |cff44ff44Gained|r (quests, loot, vendor sales, mail)|n  - |cffff4444Spent|r (repair, vendor buy, mail cost)|n  - |cffffffffNet|r (+/- since reset)|n|nValues are |cffffffffper-char persistent|r across /reload and logout.|nOffline gold (AH mail, trade) is not counted.|n|nReset: button below or |cffffff00/vcui goldreset|r.|r"] = "|cffaaaaaaПоказывает в подсказке золота рюкзака баланс с последнего ручного сброса:|n  - |cff44ff44Получено|r (задания, добыча, продажа торговцам, почта)|n  - |cffff4444Потрачено|r (починка, покупки у торговцев, стоимость почты)|n  - |cffffffffИтого|r (+/- с момента сброса)|n|nЗначения |cffffffffсохраняются отдельно для каждого персонажа|r при /reload и выходе из игры.|nЗолото, полученное офлайн (почта с аукциона, обмен), не учитывается.|n|nСброс: кнопка ниже или |cffffff00/vcui goldreset|r.|r",
    ["Reset session"] = "Сбросить сессию",
    ["Class Specific"] = "Классовые инструменты",
    ["|cffaaaaaaVampiric Touch mana tracker — shows live how much mana you've given to the group (5% of shadow damage per tick, per mana user).|n|cffffffffReset automatically on combat start.|r|r"] = "|cffaaaaaaОтслеживание маны от «Прикосновения вампира» — вживую показывает, сколько маны вы отдали группе (5% от урона от темной магии за тик, на каждого владельца маны).|n|cffffffffСбрасывается автоматически в начале боя.|r|r",
    ["|cffff8800These tools are only active while playing a Priest.|r"] = "|cffff8800Эти инструменты активны только при игре за жреца.|r",
    ["No tools yet"] = "Пока нет инструментов",
    ["|cffaaaaaaNo class-specific tools for this class yet. Got an idea? Let me know!|r"] = "|cffaaaaaaДля этого класса пока нет классовых инструментов. Есть идея? Напишите мне!|r",
    ["|cff9b6cffVT Mana:|r %d"] = "|cff9b6cffМана ПВ:|r %d",
    ["|cff9b6cffVT Mana:|r 0"] = "|cff9b6cffМана ПВ:|r 0",
    ["Vampiric Touch: %d mana given to the group."] = "«Прикосновение вампира»: группе отдано %d маны.",
    ["|cffffffffVT MANA|r"] = "|cffffffffМАНА ПВ|r",
    ["VT mana frame: x=%.0f, y=%.0f"] = "Рамка маны ПВ: x=%.0f, y=%.0f",
    ["VT mana mover active. |cff9b6cffDrag|r or |cff9b6cffarrow keys|r (SHIFT = 5px)."] = "Перемещение маны ПВ включено. |cff9b6cffПеретаскивание|r или |cff9b6cffстрелки|r (SHIFT = 5 пикс.).",
    ["VT mana mover disabled."] = "Перемещение маны ПВ выключено.",
    ["Print to chat at combat end"] = "Выводить в чат по окончании боя",
    ["Writes a summary in chat after each fight."] = "Пишет сводку в чат после каждого боя.",
    ["Reset manually"] = "Сбросить вручную",
    ["VT mana reset."] = "Мана ПВ сброшена.",
    ["Shadow DoT Tracker"] = "Отслеживание ДоТов Тьмы",
    ["|cffaaaaaaTracks your Shadow DoTs on the target. |cff44ff44Green|r = a buff is up that makes it hit harder if you recast now (TBC snapshot); |cffff4444red|r = about to expire.|r"] = "|cffaaaaaaОтслеживает ваши ДоТы Тьмы на цели. |cff44ff44Зеленый|r — действует эффект, из-за которого перезаброс сейчас ударит сильнее (снимок характеристик в TBC); |cffff4444красный|r — вот-вот закончится.|r",
    ["Bars"] = "Полосы",
    ["Icons"] = "Значки",
    ["Shadow Word: Pain"] = "Слово тьмы: Боль",
    ["Vampiric Touch"] = "Прикосновение вампира",
    ["Devouring Plague"] = "Пожирающая чума",
    ["Warning (seconds left)"] = "Предупреждение (осталось секунд)",
    ["Bar width"] = "Ширина полосы",
    ["Bar height"] = "Высота полосы",
    ["Spacing"] = "Промежуток",
    ["Color the timer text"] = "Окрашивать текст таймера",
    ["Show recast gain %"] = "Показывать прирост от перезаброса (%)",
    ["Shows how much harder a fresh cast would hit right now (e.g. +12% with a spell power proc up). Negative values mean the running DoT snapshotted stronger — keep it."] = "Показывает, насколько сильнее ударил бы свежий заброс прямо сейчас (например, +12% при активном проке силы заклинаний). Отрицательные значения означают, что действующий ДоТ снял более сильный снимок — оставьте его.",
    ["DoT Tracker"] = "Отслеживание ДоТов",
    ["|cffaaaaaaTracks your DoTs on the target. |cff44ff44Green|r = a buff is up that makes it hit harder if you recast now (TBC snapshot); |cffff4444red|r = about to expire.|r"] = "|cffaaaaaaОтслеживает ваши ДоТы на цели. |cff44ff44Зеленый|r — действует эффект, из-за которого перезаброс сейчас ударит сильнее (снимок характеристик в TBC); |cffff4444красный|r — вот-вот закончится.|r",
    ["|cffff8800Only active while playing a %s.|r"] = "|cffff8800Активно только при игре за класс %s.|r",
    ["|cffaaaaaaTracks your Warlock DoTs (Corruption, Curse of Agony, Unstable Affliction, Siphon Life, Immolate, Curse of Doom) on the target, with the same recast-snapshot readout as the Priest tracker.|r"] = "|cffaaaaaaОтслеживает ваши ДоТы чернокнижника (Порча, Проклятие агонии, Нестабильное колдовство, Похищение жизни, Прижигание, Проклятие рока) на цели, с тем же показом прироста от перезаброса, что и у отслеживания для жреца.|r",
    ["Corruption"] = "Порча",
    ["Curse of Agony"] = "Проклятие агонии",
    ["Unstable Affliction"] = "Нестабильное колдовство",
    ["Siphon Life"] = "Похищение жизни",
    ["Immolate"] = "Прижигание",
    ["Curse of Doom"] = "Проклятие рока",
    ["|cffffffffSHADOW DOTS|r"] = "|cffffffffДОТЫ ТЬМЫ|r",
    ["|cffffffffDOTS|r"] = "|cffffffffДОТЫ|r",
    ["Shadow DoTs: x=%.0f, y=%.0f"] = "ДоТы Тьмы: x=%.0f, y=%.0f",
    ["Shadow DoTs mover active. |cff9b6cffDrag|r or |cff9b6cffarrow keys|r (SHIFT = 5px)."] = "Перемещение ДоТов Тьмы включено. |cff9b6cffПеретаскивание|r или |cff9b6cffстрелки|r (SHIFT = 5 пикс.).",
    ["Shadow DoTs mover disabled."] = "Перемещение ДоТов Тьмы выключено.",
    ["Mark empty sockets"] = "Отмечать пустые гнезда",
    ["Adds a red ring around item sockets that have no gem."] = "Добавляет красное кольцо вокруг гнезд предмета, в которых нет самоцвета.",
    ["Text shadow (instead of outline)"] = "Тень текста (вместо контура)",
    ["Cleaner text with a drop shadow instead of a thick outline."] = "Более чистый текст с тенью вместо толстого контура.",
    ["|cffaaaaaaA modern round minimap with a beveled ring, zone text and clock in a slim pill. Zoom with the mouse wheel. |cffffffffShift+drag the map|r to move it — or use Unlock / the addon's own Edit Mode (/vedit). Blizzard's Edit Mode does not manage this map.|r"] = "|cffaaaaaaСовременная круглая миникарта со скошенным кольцом, названием зоны и часами в тонкой плашке. Масштаб — колесиком мыши. |cffffffffShift+перетаскивание карты|r перемещает ее — либо используйте разблокировку или собственный Режим редактирования аддона (/vedit). Режим редактирования Blizzard этой картой не управляет.|r",
    ["|cffffffffMINIMAP|r"] = "|cffffffffМИНИКАРТА|r",
    ["Minimap: x=%.0f, y=%.0f"] = "Миникарта: x=%.0f, y=%.0f",
    ["Minimap mover active. |cff9b6cffDrag|r or |cff9b6cffarrow keys|r (SHIFT = 5px)."] = "Перемещение миникарты включено. |cff9b6cffПеретаскивание|r или |cff9b6cffстрелки|r (SHIFT = 5 пикс.).",
    ["Minimap ping: %s"] = "Метка на миникарте: %s",
    ["Shape"] = "Форма",
    ["Round"] = "Круглая",
    ["Accent ring"] = "Акцентное кольцо",
    ["Ring color"] = "Цвет кольца",
    ["Accent (purple)"] = "Акцентный (фиолетовый)",
    ["Class color"] = "Цвет класса",
    ["Custom color"] = "Свой цвет",
    ["Theme color"] = "Цвет темы",
    ["Dark guild & communities window"] = "Темное окно гильдии и сообществ",
    ["Restyles the guild and communities window to the same dark look. Turning it off needs a /reload."] = "Перекрашивает окно гильдии и сообществ в тот же темный вид. Для выключения нужен /reload.",
    ["Debuffs on target (yours only)"] = "Отрицательные эффекты на цели (только ваши)",
    ["Missing buffs (reminder)"] = "Отсутствующие эффекты (напоминание)",
    ["|cffaaaaaaIcons appear while YOUR debuff/DoT is on the target, with its remaining time. Add the debuff by name or ID.|r"] = "|cffaaaaaaЗначки появляются, пока ВАШ отрицательный эффект или ДоТ висит на цели, с оставшимся временем. Добавьте эффект по названию или ID.|r",
    ["|cffaaaaaaIcons appear while the buff is MISSING on you - a reminder for weapon oils, blessings, food buffs. Add the buff by name or ID.|r"] = "|cffaaaaaaЗначки появляются, пока эффекта на вас НЕТ, — напоминание про масла для оружия, благословения и еду. Добавьте эффект по названию или ID.|r",
    ["Tint blue when out of mana"] = "Подсвечивать синим при нехватке маны",
    ["Tint red when out of range"] = "Подсвечивать красным вне радиуса",
    ["Needs a target; uses the spell's own range."] = "Нужна цель; используется собственный радиус заклинания.",
    ["Auto-track equipped trinkets"] = "Автоотслеживание надетых аксессуаров",
    ["Keeps both equipped trinkets in this group automatically - they follow along when you swap trinkets."] = "Автоматически держит оба надетых аксессуара в этой группе — они меняются вместе со сменой аксессуаров.",
    ["Duplicate"] = "Дублировать",
    ["(copy)"] = "(копия)",
    ["Show tooltips on hover"] = "Показывать подсказки при наведении",
    ["The icons then intercept the mouse - leave this off if the bar sits over clickable UI."] = "Тогда значки перехватывают мышь — оставьте выключенным, если панель находится над кликабельным интерфейсом.",
    ["Copy the link with Ctrl+C:"] = "Скопируйте ссылку через Ctrl+C:",
    ["Click: copy link"] = "Щелчок: скопировать ссылку",
    ["|cffaaaaaaColors everything that is purple today in the color of your choice - sidebar, borders, highlights, bars. A /reload applies it everywhere.|r"] = "|cffaaaaaaОкрашивает все, что сегодня фиолетовое, в выбранный вами цвет — боковую панель, каймы, подсветку, полосы. /reload применяет это везде.|r",
    ["Preset"] = "Предустановка",
    ["Purple (default)"] = "Фиолетовый (по умолчанию)",
    ["Turquoise"] = "Бирюзовый",
    ["Pink"] = "Розовый",
    ["Orange"] = "Оранжевый",
    ["Theme color changed. /reload applies it to everything (elements already drawn keep the old color until then)."] = "Цвет темы изменен. /reload применит его ко всему (уже отрисованные элементы до этого сохранят прежний цвет).",
    ["Custom ring color"] = "Свой цвет кольца",
    ["A thin colored line around the dark ring (round shape only)."] = "Тонкая цветная линия вокруг темного кольца (только для круглой формы).",
    ["Zone panel"] = "Панель зоны",
    ["Zone text and clock"] = "Название зоны и часы",
    ["Above the map"] = "Над картой",
    ["Below the map"] = "Под картой",
    ["Hidden"] = "Скрыто",
    ["Show clock"] = "Показывать часы",
    ["Show date"] = "Показывать дату",
    ["Shows the date next to the clock. Click it to open the calendar."] = "Показывает дату рядом с часами. Щелчок по ней открывает календарь.",
    ["Buttons"] = "Кнопки",
    ["Zoom buttons (+/-)"] = "Кнопки масштаба (+/-)",
    ["Shows a flat + and - on the right edge of the map. The mouse wheel always zooms too."] = "Показывает плоские + и - у правого края карты. Колесико мыши тоже всегда масштабирует.",
    ["Show day/night button"] = "Показывать кнопку дня/ночи",
    ["Restyle addon buttons"] = "Переоформлять кнопки аддонов",
    ["Removes the gold borders from other addons' minimap buttons and gives them a clean round look. Turning this off needs a /reload."] = "Убирает золотые каймы с кнопок других аддонов на миникарте и придает им чистый круглый вид. Для выключения нужен /reload.",
    ["Addon buttons only on mouseover"] = "Кнопки аддонов только при наведении",
    ["Hides other addons' minimap buttons until the mouse is over the minimap."] = "Скрывает кнопки других аддонов на миникарте, пока мышь не наведена на миникарту.",
    ["Ping in chat"] = "Метка в чат",
    ["Prints who pinged the minimap."] = "Сообщает, кто поставил метку на миникарте.",
    ["Totem Bar"] = "Панель тотемов",
    ["|cffaaaaaa|cffffffffLeft-click|r an icon to (re)cast that element's totem, |cffffffffhover|r a slot to pick which totem from the icon list, |cffffffffmiddle-click|r to recall all totems. The icon border turns red just before the totem expires.|r"] = "|cffaaaaaa|cffffffffЛевый щелчок|r по значку — (пере)вызвать тотем этой стихии, |cffffffffнаведение|r на слот — выбрать тотем из списка значков, |cffffffffсредний щелчок|r — отозвать все тотемы. Кайма значка становится красной незадолго до окончания действия тотема.|r",
    ["|cffff8800Only active while playing a Shaman.|r"] = "|cffff8800Активно только при игре за шамана.|r",
    ["Totem set"] = "Набор тотемов",
    ["Active set"] = "Активный набор",
    ["Set name"] = "Название набора",
    ["New set"] = "Новый набор",
    ["Delete set"] = "Удалить набор",
    ["(auto: last cast)"] = "(авто: последний вызванный)",
    ["|cff888888(cast a totem to add it here)|r"] = "|cff888888(вызовите тотем, чтобы добавить его сюда)|r",
    ["Shown elements"] = "Отображаемые стихии",
    ["Sound before a totem expires"] = "Звук перед окончанием действия тотема",
    ["Icon border (action-bar style)"] = "Кайма значка (в стиле панели команд)",
    ["Style"] = "Стиль",
    ["VuloUI (dark)"] = "VuloUI (темный)",
    ["Classic (metal)"] = "Классический (металл)",
    ["Flyout direction"] = "Направление раскрытия",
    ["Which way the totem picker opens when you hover a slot. Automatic picks the side away from the screen edge."] = "В какую сторону открывается выбор тотемов при наведении на слот. «Автоматически» выбирает сторону подальше от края экрана.",
    ["Automatic"] = "Автоматически",
    ["Upwards"] = "Вверх",
    ["Downwards"] = "Вниз",
    ["To the left"] = "Влево",
    ["To the right"] = "Вправо",
    ["Open flyout in combat"] = "Открывать раскрытие в бою",
    ["Tooltip with cooldown on hover"] = "Подсказка с восстановлением при наведении",
    ["Hovering a totem slot or a picker icon shows the totem name and its remaining cooldown."] = "При наведении на слот тотема или значок в списке показывается название тотема и его оставшееся восстановление.",
    ["Off = hovering a slot never opens the totem picker while you are fighting (clicks still cast). The picker now also closes itself on mouse-out and after every cast, even in combat."] = "Выключено — наведение на слот никогда не открывает выбор тотемов во время боя (щелчки по-прежнему вызывают тотем). Список теперь также закрывается сам при уходе мыши и после каждого вызова, даже в бою.",
    ["Earth"] = "Земля",
    ["Water"] = "Вода",
    ["|cffffffffTOTEMS|r"] = "|cffffffffТОТЕМЫ|r",
    ["Totems: x=%.0f, y=%.0f"] = "Тотемы: x=%.0f, y=%.0f",
    ["Totem timer mover active. |cff9b6cffDrag|r or |cff9b6cffarrow keys|r (SHIFT = 5px)."] = "Перемещение таймера тотемов включено. |cff9b6cffПеретаскивание|r или |cff9b6cffстрелки|r (SHIFT = 5 пикс.).",
    ["Totem timer mover disabled."] = "Перемещение таймера тотемов выключено.",
    ["|cffff5555Class tool error:|r %s"] = "|cffff5555Ошибка классового инструмента:|r %s",
    ["EDIT MODE"] = "РЕЖИМ РЕДАКТИРОВАНИЯ",
    ["Edit Mode"] = "Режим редактирования",
    ["Open Edit Mode"] = "Открыть Режим редактирования",
    ["Close Edit Mode and lock all windows. Your changes stay applied."] = "Закрыть Режим редактирования и закрепить все окна. Ваши изменения останутся.",
    ["Keep the current arrangement and carry on editing. Discard then returns to this point instead of to how things looked when Edit Mode opened."] = "Сохранить текущую расстановку и продолжить редактирование. «Отменить» после этого вернет к этой точке, а не к тому, как все выглядело при открытии Режима редактирования.",
    ["Window positions saved."] = "Положения окон сохранены.",
    ["Exit"] = "Выход",
    ["Close"] = "Закрыть",
    ["Reset"] = "Сброс",
    ["Reset this frame"] = "Сбросить эту рамку",
    ["Reset all VuloUI window positions to the screen centre."] = "Сбросить положения всех окон VuloUI к центру экрана.",
    ["Reset all VuloUI window positions to the screen centre?"] = "Сбросить положения всех окон VuloUI к центру экрана?",
    ["Done — lock everything"] = "Готово — закрепить все",
    ["Grid"] = "Сетка",
    ["Show an alignment grid."] = "Показывать сетку выравнивания.",
    ["%d frames here - hold Alt to cycle"] = "Здесь рамок: %d — удерживайте Alt для перебора",
    ["Drag a box, or hover it and use the arrow keys (Shift = 5px). Shift+click to select several and drag them together."] = "Перетащите блок или наведите на него и используйте стрелки (Shift = 5 пикс.). Shift+щелчок выделяет несколько блоков, чтобы двигать их вместе.",
    ["Which screen point the frame is pinned to (keeps it put across resolution changes)."] = "К какой точке экрана привязана рамка (сохраняет положение при смене разрешения).",
    ["ANCHOR"] = "ПРИВЯЗКА",
    ["POSITION"] = "ПОЛОЖЕНИЕ",
    ["SCALE"] = "МАСШТАБ",
    ["FREE MOVE"] = "СВОБОДНОЕ ПЕРЕМЕЩЕНИЕ",
    ["FOLLOW WINDOW"] = "СЛЕДОВАТЬ ЗА ОКНОМ",
    ["Pins this window to another one - it then moves along whenever that window is moved. Dragging this window keeps the pin and just updates the distance."] = "Прикрепляет это окно к другому — тогда оно перемещается вместе с ним. Перетаскивание этого окна сохраняет привязку и просто обновляет расстояние.",
    ["Not possible - that would create a loop."] = "Невозможно — это создаст циклическую связь.",
    ["|cffaaaaaaOne click: makes a profile named after your class (copied from the current one) and loads it for this class automatically. Run it once on each character — every class then keeps its own cooldown bars, frames and settings.|r"] = "|cffaaaaaaОдин щелчок: создает профиль с названием вашего класса (копию текущего) и автоматически загружает его для этого класса. Выполните это один раз на каждом персонаже — тогда у каждого класса будут свои панели восстановления, рамки и настройки.|r",
    ["Hide TargetFrame background"] = "Скрыть фон TargetFrame",
    ["Permanently hides the dark background element of the TargetFrame."] = "Навсегда скрывает темный элемент фона у TargetFrame.",
    ["Target Frame"] = "Рамка цели",
    ["|cffaaaaaaAdds the modern Target/Focus frame extras the default Anniversary UI is missing - all cosmetic, no taint.|r"] = "|cffaaaaaaДобавляет современные дополнения к рамкам цели и фокуса, которых нет в стандартном интерфейсе Anniversary — только внешний вид, без нарушения защищенного кода.|r",
    ["Shows your threat percentage on the target (and focus) above the frame, coloured by threat status."] = "Показывает вашу угрозу в процентах на цели (и фокусе) над рамкой, с цветом по уровню угрозы.",
    ["Glows the target (and focus) frame in yellow/orange/red as your threat rises."] = "Подсвечивает рамку цели (и фокуса) желтым, оранжевым или красным по мере роста вашей угрозы.",
    ["Shows the target's class crest on the frame when you target a player."] = "Показывает на рамке герб класса цели, когда вы выбираете игрока.",
    ["Also apply to the Focus frame"] = "Применять также к рамке фокуса",
    ["Arena Frames"] = "Рамки арены",
    ["Enhances the Arena enemy frames: move/scale, class colors, class icons, PvP trinket CD, DR tracking, castbar, drag&drop layout."] = "Улучшает рамки противников на арене: перемещение и масштаб, цвета классов, значки классов, восстановление аксессуара PvP, отслеживание DR, полоса заклинания, макет перетаскиванием.",
    ["Layout"] = "Макет",
    ["|cffffffffArena Frames|r"] = "|cffffffffРамки арены|r",
    ["Arena Frames position saved."] = "Положение рамок арены сохранено.",
    ["|cff9b6cffArenaFrames Unlock|r  |cffaaaaaa(Scale: %.2f)|r"] = "|cff9b6cffРазблокировка рамок арены|r  |cffaaaaaa(Масштаб: %.2f)|r",
    ["|cff9b6cffArenaFrames Unlock|r"] = "|cff9b6cffРазблокировка рамок арены|r",
    ["Drag the purple overlay above the frames to move.\nMouse wheel on overlay = scale. /vcui arenaframes to finish."] = "Перетащите фиолетовый блок над рамками, чтобы переместить их.\\nКолесо мыши на блоке = масштаб. /vcui arenaframes — завершить.",
    ["In unlock mode a purple overlay appears above the frames. Click + drag to move, mouse wheel to scale."] = "В режиме разблокировки над рамками появляется фиолетовый блок. Нажмите и перетащите, чтобы переместить, колесо мыши меняет масштаб.",
    ["Layout (Order)"] = "Макет (порядок)",
    ["Order of the arena frames. Use up/down to move slots 1-5."] = "Порядок рамок арены. Кнопками вверх и вниз переставляйте слоты 1-5.",
    ["Spacing between frames"] = "Расстояние между рамками",
    ["Shows an icon with cooldown spiral next to the arena frame when the opponent used their PvP trinket."] = "Показывает значок со спиралью восстановления рядом с рамкой арены, когда противник применил аксессуар PvP.",
    ["Left of frame"] = "Слева от рамки",
    ["Right of frame"] = "Справа от рамки",
    ["Shows icons next to each arena frame for active DR categories (Stun, Fear, Polymorph etc.) with color indicator: |cff00ff00green|r = full, |cffffff00yellow|r = 1/2, |cffff8000orange|r = 1/4, |cffff0000red|r = immune."] = "Показывает рядом с каждой рамкой арены значки активных категорий DR (оглушение, устрашение, превращение и т. д.) с цветовым указателем: |cff00ff00зеленый|r = полностью, |cffffff00желтый|r = 1/2, |cffff8000оранжевый|r = 1/4, |cffff0000красный|r = невосприимчивость.",
    ["Shows a castbar below the frame when the opponent casts or channels."] = "Показывает полосу заклинания под рамкой, когда противник читает или поддерживает заклинание.",
    ["Hides the 'Group 1'/'Group 2' labels above the compact raid frames."] = "Скрывает надписи «Группа 1» и «Группа 2» над компактными рейдовыми рамками.",
    ["Minimap module disabled — /reload restores the default layout completely."] = "Модуль миникарты отключен — /reload полностью восстановит стандартный макет.",
    ["Copies the selected group with all entries and layout settings."] = "Копирует выбранную группу со всеми записями и настройками макета.",
    ["Snap"] = "Прилипание",
    ["Snap windows to the grid while dragging."] = "Прилипание окон к сетке при перетаскивании.",
    ["Discard"] = "Отменить изменения",
    ["Discard changes and revert every window to how it was when Edit Mode opened."] = "Отменить изменения и вернуть все окна к состоянию на момент открытия Режима редактирования.",
    ["Discard all changes made since opening Edit Mode?"] = "Отменить все изменения, сделанные после открытия Режима редактирования?",
    ["Pin this frame to a screen edge/corner so it stays put across resolution changes. Off keeps it centred."] = "Прикрепляет эту рамку к краю или углу экрана, чтобы она оставалась на месте при смене разрешения. Выкл. оставляет ее по центру.",
    ["LAYOUTS"] = "МАКЕТЫ",
    ["Layouts"] = "Макеты",
    ["No layouts saved"] = "Нет сохраненных макетов",
    ["No layout selected."] = "Макет не выбран.",
    ["Save, load, export and import named window layouts."] = "Сохранение, загрузка, экспорт и импорт именованных макетов окон.",
    ["Save your window arrangement, then load or share it any time."] = "Сохраните расположение своих окон, чтобы в любой момент загрузить его или поделиться им.",
    ["Pick a saved layout to load, delete or export."] = "Выберите сохраненный макет, чтобы загрузить, удалить или экспортировать его.",
    ["Name for this layout:"] = "Название этого макета:",
    ["Delete layout '%s'?"] = "Удалить макет «%s»?",
    ["Layout '%s' saved."] = "Макет «%s» сохранен.",
    ["Applied layout '%s' (%d frames)."] = "Макет «%s» применен (рамок: %d).",
    ["Layout '%s' imported."] = "Макет «%s» импортирован.",
    ["Paste a layout string and confirm:"] = "Вставьте строку макета и подтвердите:",
    ["|cffffffffARENA FRAMES|r"] = "|cffffffffРАМКИ АРЕНЫ|r",
    ["|cffaaaaaaMove everything in one editor: VuloUI windows and Blizzard's frames (player, target, focus, minimap, buffs). They snap to a shared grid.|r"] = "|cffaaaaaaПеремещайте все в одном редакторе: окна VuloUI и рамки Blizzard (игрок, цель, фокус, миникарта, эффекты). Они прилипают к общей сетке.|r",
    ["|cff888888• Drag a purple box to move that frame.|n• Hover a box, then arrow keys fine-tune (SHIFT = 5px).|n• Right-click a box for exact X / Y.|n• |cffffffff/vedit|r toggles Edit Mode too.|r"] = "|cff888888• Перетащите фиолетовый блок, чтобы переместить эту рамку.|n• Наведите курсор на блок, затем стрелками задайте точное положение (SHIFT = 5 пикс.).|n• Щелкните по блоку правой кнопкой для точных X / Y.|n• |cffffffff/vedit|r тоже переключает Режим редактирования.|r",
    ["Enable 'Target and Focus' in Blizzard's Edit Mode settings, then /reload, so VuloUI can move the target/focus frame."] = "Включите «Цель и фокус» в настройках Режима редактирования Blizzard, затем выполните /reload, чтобы VuloUI мог перемещать рамку цели и фокуса.",
    ["Darkens and desaturates Blizzard's default UI artwork (unit frames, minimap, action bars) to a neutral dark tone. Keeps Blizzard's frames — it just re-tints them."] = "Затемняет и обесцвечивает стандартную графику интерфейса Blizzard (рамки существ, миникарта, панели команд) до нейтрального темного тона. Рамки Blizzard сохраняются — они лишь перекрашиваются.",
    ["|cffaaaaaaDarkens and desaturates Blizzard's default artwork — unit frames, minimap and action bars — to a neutral dark tone. Reversible: turn it off and the gold look returns.|r"] = "|cffaaaaaaЗатемняет и обесцвечивает стандартную графику Blizzard — рамки существ, миникарту и панели команд — до нейтрального темного тона. Обратимо: выключите, и золотой вид вернется.|r",
    ["Unit frames"] = "Рамки существ",
    ["Player, target, focus, pet and party frame borders."] = "Каймы рамок игрока, цели, фокуса, питомца и группы.",
    ["Elite dragon border for your player frame, plus real health, threat display and the rare-elite border for the target and focus frames."] = "Кайма с элитным драконом для рамки игрока, а также реальное здоровье, отображение угрозы и кайма редкого элитного для рамок цели и фокуса.",
    ["Rare-Elite border"] = "Кайма редкого элитного",
    ["Shows the winged silver-dragon Rare-Elite border on rare-elite mobs."] = "Показывает кайму с крылатым серебряным драконом на редких элитных существах.",
    ["Minimap border, compass, zoom and tracking buttons."] = "Кайма мини-карты, компас, масштаб и кнопки слежения.",
    ["Action button borders"] = "Каймы кнопок панели команд",
    ["Also tints the border ring around every action button. Optional — leave off if it looks too flat."] = "Также окрашивает кольцо каймы вокруг каждой кнопки панели команд. По желанию — отключите, если вид кажется слишком плоским.",
    ["Action bar dark border"] = "Темная кайма панели команд",
    ["Adds the dark Button Skin border to the action bars while Dark Mode is on (and removes it when Dark Mode turns off). You can also switch it on with Dark Mode off in the Button Skin module."] = "Добавляет темную кайму Button Skin к панелям команд, пока включен Dark Mode (и убирает ее при выключении Dark Mode). Ее также можно включить при выключенном Dark Mode в модуле Button Skin.",
    ["Tints the backpack, bag and keyring button borders."] = "Окрашивает каймы кнопок рюкзака, сумок и связки ключей.",
    ["|cffaaaaaaNote: if the Player & Target Frame module's |cffffffffThreat glow|r is on, threat colouring takes over the target/focus border while you have aggro — that's intended.|r"] = "|cffaaaaaaПримечание: если в модуле Player & Target Frame включено |cffffffffсвечение угрозы|r, то при наличии аггро окраска угрозы перекрывает кайму цели/фокуса — так и задумано.|r",
    ["|cffaaaaaaAction button borders are also managed by the Button Skin module — if that's on, it controls the buttons instead.|r"] = "|cffaaaaaaКаймами кнопок панели команд также управляет модуль Button Skin — если он включен, кнопками управляет он.|r",
    ["Quality borders"] = "Каймы по качеству",
    ["Colour each item's border by its rarity."] = "Окрашивать кайму каждого предмета по его редкости.",
    ["Border style"] = "Стиль каймы",
    ["Border texture"] = "Текстура каймы",
    ["Border colour"] = "Цвет каймы",
    ["|cff9b6cffButton border / icon style lives in the Dark Skin module (Action Bars > Bar style): square, accent edge, shadow and more.|r"] = "|cff9b6cffСтиль каймы кнопок и значков находится в модуле Dark Skin (Action Bars → Bar style): квадрат, акцентная кайма, тень и другое.|r",
    ["Clips the fill and background to a rounded shape. The line border stays square, so a thin border may show slightly at the corners."] = "Обрезает заливку и фон по скругленной форме. Линейная кайма остается квадратной, поэтому тонкая кайма может слегка выступать по углам.",
    ["Colour border by school"] = "Окрашивать кайму по школе магии",
    ["Aura borders take the colour of their school: magic blue, curse purple, disease orange, poison green."] = "Каймы эффектов принимают цвет своей школы магии: магия — синий, проклятие — фиолетовый, болезнь — оранжевый, яд — зеленый.",
    ["Reset ALL VuloClassicUI settings for every character on this account? This cannot be undone."] = "Сбросить ВСЕ настройки VuloClassicUI для всех персонажей этой учетной записи? Отменить это действие нельзя.",
    ["Swing Timer switched off: it only tracks melee auto-attacks, which this character's talents do not use."] = "Таймер атаки отключён: он отслеживает только автоатаки в ближнем бою, которые таланты этого персонажа не используют.",
    ["|cffff5555Settings migration %s failed:|r %s"] = "|cffff5555Не удалось перенести настройки %s:|r %s",
    ["Plays a raid warning sound the moment an opponent uses their PvP trinket."] = "Проигрывает звук рейдового предупреждения, как только противник использует PvP-аксессуар.",
    ["Flashes the icon briefly when an opponent uses their PvP trinket."] = "Кратко подсвечивает значок, когда противник использует PvP-аксессуар.",
    ["Icon gap"] = "Отступ значка",
    ["Distance between the icon and the bar."] = "Расстояние между значком и полосой.",
    ["Accent colour"] = "Цвет акцента",
    ["Used for the bar while the fill mode is not a texture, and for channelled casts on Blizzard's own castbar."] = "Используется для полосы, пока режим заливки не является текстурой, и для поддерживаемых заклинаний на собственной полосе Blizzard.",
    ["Cast finished"] = "Заклинание завершено",
    ["The bar flashes in this colour when a cast completes."] = "Полоса вспыхивает этим цветом, когда заклинание завершается.",
    ["Cast interrupted"] = "Заклинание прервано",
    ["The bar flashes in this colour when a cast is interrupted or fails."] = "Полоса вспыхивает этим цветом, когда заклинание прерывают или оно не удаётся.",
    ["Fade-in time"] = "Время появления",
    ["How long an icon takes to appear. 0 makes it show instantly."] = "Сколько значок появляется. 0 показывает его сразу.",
    [" and %d item(s)"] = " и %d предмет(ов)",
    ["/vlfg toggles the group board."] = "/vlfg открывает или закрывает доску групп.",
    ["Auto-apply a lure when the pole has none"] = "Автоматически наносить наживку, если её нет на удочке",
    ["Auto-equip a fishing pole if none is worn"] = "Автоматически брать удочку, если ни одной не надето",
    ["Auto-loot while fishing"] = "Автоматический сбор добычи во время рыбалки",
    ["Bags are full — some items were left in the mail."] = "Сумки полны — часть предметов осталась в почте.",
    ["Boost fishing sound (hear the bite clearly)"] = "Усилить звук рыбалки (чтобы чётко слышать поклёвку)",
    ["Burning Crusade Dungeons"] = "Подземелья Burning Crusade",
    ["Burning Crusade Raids"] = "Рейды Burning Crusade",
    ["Can't change the fishing key in combat."] = "Нельзя сменить клавишу рыбалки в бою.",
    ["Classic Dungeons"] = "Подземелья Classic",
    ["Classic Raids"] = "Рейды Classic",
    ["Clear key"] = "Сбросить клавишу",
    ["Extra items & macros"] = "Дополнительные предметы и макросы",
    ["Fishing key cleared."] = "Клавиша рыбалки сброшена.",
    ["Fishing key set to: %s"] = "Клавиша рыбалки: %s",
    ["Fishing key: %s  —  click to change"] = "Клавиша рыбалки: %s  —  нажмите, чтобы изменить",
    ["Fishing sound volume"] = "Громкость звука рыбалки",
    ["Friends"] = "Друзья",
    ["Guild"] = "Гильдия",
    ["H"] = "Г",
    ["Hide the reel error spam while fishing"] = "Скрывать ошибки подсечки во время рыбалки",
    ["In Progress"] = "Выполняется",
    ["Invite"] = "Пригласить",
    ["Keep requests for (minutes)"] = "Хранить заявки (минут)",
    ["Keep sound audible when the game is in the background"] = "Оставлять звук слышным, когда игра свёрнута",
    ["Keep this many bag slots free"] = "Оставлять столько свободных ячеек в сумках",
    ["Mail emptied: looted %s%s."] = "Почта очищена: получено %s%s.",
    ["No contacts yet"] = "Контактов пока нет",
    ["No groups forming right now."] = "Сейчас никто не собирает группу.",
    ["Not all mail is shown — reopen the mailbox and click again for the rest."] = "Показана не вся почта — откройте ящик заново и нажмите ещё раз для остального.",
    ["One-key reel (soft-target interact)"] = "Подсечка одной клавишей (мягкое взаимодействие)",
    ["Open All"] = "Открыть всё",
    ["Press the key for fishing  (ESC to cancel)"] = "Нажмите клавишу для рыбалки  (ESC — отмена)",
    ["Print a looted summary"] = "Выводить сводку по добыче",
    ["Recently mailed"] = "Недавние получатели",
    ["Recipient dropdown on the Send tab"] = "Список получателей на вкладке отправки",
    ["Scan guild chat"] = "Сканировать чат гильдии",
    ["Scan say / yell"] = "Сканировать речь и крик",
    ["Scan world / trade / LFG channels"] = "Сканировать каналы мира, торговли и поиска группы",
    ["Set fishing key"] = "Задать клавишу рыбалки",
    ["Slot %d"] = "Ячейка %d",
    ["Speed (seconds between actions)"] = "Скорость (секунд между действиями)",
    ["Take item attachments"] = "Забирать вложенные предметы",
    ["Take money"] = "Забирать деньги",
    ["While the bobber is out, maxes effect + master volume and dims music/ambience so the splash is easy to hear. Restored when you reel in."] = "Пока поплавок в воде, громкость эффектов и общая громкость выводятся на максимум, а музыка и звуки окружения приглушаются, чтобы хорошо слышать всплеск. Восстанавливается при подсечке.",
    ["While the bobber is out, the same key interacts with it to reel in. Needs soft-target interaction, which is enabled only while fishing and restored afterwards."] = "Пока поплавок в воде, та же клавиша взаимодействует с ним для подсечки. Требуется мягкое взаимодействие с целью: оно включается только на время рыбалки и потом восстанавливается.",
    ["Whisper"] = "Шепнуть",
    ["Who"] = "Кто",
    ["Your characters"] = "Ваши персонажи",
    ["now"] = "сейчас",
    ["|cffaaaaaaAdds an 'Open All' button to the mailbox. It takes every attachment and coin, skipping CoD and GM mail. Shift-click the button to ignore the filters and take everything.|r"] = "|cffaaaaaaДобавляет в почтовый ящик кнопку «Открыть всё». Она забирает все вложения и деньги, пропуская наложенный платёж и письма ГМ. Shift+щелчок по кнопке игнорирует фильтры и забирает всё.|r",
    ["|cffaaaaaaItems or macros also used by the key while fishing — only when ready (off cooldown, buff missing, conditions met), then it goes back to casting. Type an item name or ID, shift-click an item into the box, or paste a /macro.|r"] = "|cffaaaaaaПредметы или макросы, которые клавиша также использует во время рыбалки — только когда они готовы (восстановление прошло, эффекта нет, условия выполнены), а потом снова забрасывает. Введите название или ID предмета, вставьте предмет через Shift+щелчок или вставьте /макрос.|r",
    ["|cffaaaaaaOne key does it all: cast, reel in, and apply a lure — then auto-loots. Set a key below, face some water, and press it.|r"] = "|cffaaaaaaОдна клавиша делает всё: забрасывает, подсекает и наносит наживку — а потом собирает добычу. Задайте клавишу ниже, повернитесь к воде и нажмите.|r",
    ["|cffff5555Arena submodule OnDisable error:|r %s"] = "|cffff5555Ошибка OnDisable подмодуля арены:|r %s",
    -- Patch notes, module descriptions, anchors, embedded engine (sweep 2026-07)
    ["Languages"] = "Языки",
    ["Reminders (new module)"] = "Напоминания (новый модуль)",
    ["Arena"] = "Арена",
    ["Totems"] = "Тотемы",
    ["Fixes"] = "Исправления",
    ["Resource Bar"] = "Полоса ресурса",
    ["Settings Window"] = "Окно настроек",
    ["Character Window"] = "Окно персонажа",
    ["Nameplates (German: Namensplaketten)"] = "Индикаторы здоровья (нем.: Namensplaketten)",
    ["German client"] = "Немецкий клиент",
    ["Performance"] = "Производительность",
    ["Equipment Sets"] = "Комплекты экипировки",
    ["NEW — Guild Bank"] = "НОВОЕ — Банк гильдии",
    ["Friends & Reskins"] = "Друзья и оформление",
    ["Bags & Bank"] = "Сумки и банк",
    ["NEW — Bags & Bank"] = "НОВОЕ — Сумки и банк",
    ["NEW — Chat"] = "НОВОЕ — Чат",
    ["NEW — Dark Mode"] = "НОВОЕ — Темный режим",
    ["Spanish, French, Italian, Portuguese, Russian and Korean. All six are complete — every one of the 2244 texts is translated, nothing falls back to English. Spanish also serves Latin American clients. Choose your language under General, or leave it on Auto."] = "Испанский, французский, итальянский, португальский, русский и корейский. Все шесть языков полностью готовы — переведен каждый из 2244 текстов, ничего не остается на английском. Испанский также обслуживает латиноамериканские клиенты. Выберите язык в разделе «Общее» или оставьте «Авто».",
    ["Shows what you are missing before a pull: weapon oils and stones, blessings, food and flask buffs, the aura or stance you forgot to set. Click a reminder to cast or use it. Off by default, found under Quality of Life."] = "Показывает перед боем, чего вам не хватает: масла и камни для оружия, благословения, эффекты еды и настоев, аура или стойка, которую вы забыли включить. Нажмите на напоминание, чтобы произнести заклинание или использовать предмет. По умолчанию выключено, находится в разделе «Удобства».",
    ["A spark at the bar's fill point, rounded corners, aura rows you can assign freely, and your own damage-over-time effects on a row of their own."] = "Искра в точке заполнения полосы, скругленные углы, ряды аур со свободным распределением и ваши собственные периодические эффекты урона в отдельном ряду.",
    ["Aura borders take the colour of their spell school, and an aura flashes shortly before it runs out."] = "Каймы аур принимают цвет школы своего заклинания, а незадолго до окончания аура мигает.",
    ["Level and elite text, plus overall scale and vertical offset per plate."] = "Текст уровня и элитности, а также общий масштаб и вертикальное смещение для каждого индикатора.",
    ["A window can take its width or height from another window and keep it."] = "Окно может перенимать ширину или высоту у другого окна и сохранять ее.",
    ["Save button. While dragging, hold Shift to lock one axis."] = "Кнопка сохранения. Во время перетаскивания удерживайте Shift, чтобы зафиксировать одну ось.",
    ["Trinket and racial cooldowns, Shadow Sight timer, a ring on the class icon for the most important aura, and range checking."] = "Восстановление аксессуаров и расовых способностей, таймер «Темного зрения», кольцо на значке класса для самой важной ауры и проверка дальности.",
    ["Totem icons grey out once you leave the totem's range and regain their colour when you come back."] = "Значки тотемов тускнеют, когда вы покидаете радиус действия тотема, и снова обретают цвет, когда вы возвращаетесь.",
    ["The character sheet and spellbook open in combat again. The action bars no longer set a protected field from our own code, which was the real cause."] = "Окно персонажа и книга заклинаний снова открываются в бою. Панели команд больше не задают защищенное поле из нашего собственного кода — это и было настоящей причиной.",
    ["The melee swing timer is off by default and only loads for melee classes and specialisations."] = "Таймер атаки ближнего боя по умолчанию выключен и загружается только для классов и специализаций ближнего боя.",
    ["Sliders got a proper look: soft edges, an inner shadow and a smoother hover."] = "Ползунки получили достойный вид: мягкие края, внутренняя тень и более плавное наведение.",
    ["Own icons for the three collection pages, and class icons on the class tabs."] = "Собственные значки для трех страниц коллекций и значки классов на вкладках классов.",
    ["Anchor a window to another one's edge (left/right/top/bottom) — the gap is kept edge-to-edge, so it survives either window being resized."] = "Привязывайте окно к краю другого (слева/справа/сверху/снизу) — отступ сохраняется от края до края и потому переживает изменение размера любого из окон.",
    ["Click-to-anchor: press \"Anchor to window...\" in a window's panel, then click the target window. Loop and self-anchor are blocked."] = "Привязка щелчком: нажмите «Привязать к окну...» в панели окна, затем нажмите на целевое окно. Замкнутый круг и привязка к самому себе заблокированы.",
    ["While dragging, alignment lines now also show the pixel distance to the window you line up with."] = "Во время перетаскивания линии выравнивания теперь также показывают расстояние в пикселях до окна, по которому вы выравниваетесь.",
    ["Discard button — snapshots the layout when you open Edit Mode and restores it (positions, scale, anchors and links) if you discard."] = "Кнопка «Отменить» — запоминает расстановку при открытии Режима редактирования и восстанавливает ее (позиции, масштаб, привязки и связи), если вы отменяете изменения.",
    ["The drag area now covers the whole dark chat panel down to the edit box, not just the narrow message strip."] = "Область перетаскивания теперь охватывает всю темную панель чата вплоть до поля ввода, а не только узкую полосу сообщений.",
    ["Fixed right-click on the chat window not opening its settings panel in Edit Mode."] = "Исправлено: правый щелчок по окну чата не открывал его панель настроек в Режиме редактирования.",
    ["Interrupt help on the cast bar: own colours while your interrupt is on cooldown or ready, a tick marking where it comes back mid-cast, a shield on uninterruptible casts and an interrupt flash that can show who landed the kick."] = "Помощь по прерыванию на полосе заклинания: свои цвета, пока ваше прерывание восстанавливается или готово, отметка, показывающая, где оно вернется во время произнесения, щит на непрерываемых заклинаниях и вспышка прерывания, которая может показывать, кто выполнил сбивание.",
    ["Cast bar suite: icon side and scale, remaining time, own background, channel colour, a warning colour when the cast aims at YOU — and on your target the cast bar lines up flush with the health bar including its border."] = "Набор возможностей полосы заклинания: сторона и масштаб значка, оставшееся время, собственный фон, цвет поддерживаемых заклинаний, предупреждающий цвет, когда заклинание нацелено на ВАС, — а у вашей цели полоса заклинания выравнивается вплотную к полосе здоровья вместе с ее каймой.",
    ["Execute line, target and mouseover effects, crowd control section, combo point shapes and placement, per-element position, size and text-size controls plus a font picker."] = "Линия добивания, эффекты цели и наведения мыши, раздел контроля, формы и размещение очков серии приемов, настройки положения, размера и размера текста для каждого элемента, а также выбор шрифта.",
    ["The options page carries a clickable live preview that stays pinned while you scroll — click any element to jump to its settings."] = "Страница настроек содержит кликабельный живой предпросмотр, который остается закрепленным при прокрутке — нажмите на любой элемент, чтобы перейти к его настройкам.",
    ["Smooth health movement with a damage trail, value plus percent text layouts with short numbers, and a decimal toggle for aura timers."] = "Плавное движение здоровья со следом урона, варианты текста «значение плюс проценты» с сокращенными числами и переключатель десятичных долей для таймеров аур.",
    ["Per-bar visibility conditions (instances, mounted, target, group), modifier paging, quick keybind mode (/vkb), a sixth bar, growth directions, button text styling and cooldown look options."] = "Условия видимости для каждой панели (подземелья, верхом, цель, группа), перелистывание модификаторами, режим быстрой привязки клавиш (/vkb), шестая панель, направления роста, оформление текста кнопок и настройки вида восстановления.",
    ["Micro menu and bag bar modern style: flat dark strips with an own monochrome icon set, plus world map, friends list, group finder, shop and key ring buttons."] = "Современный стиль микроменю и панели сумок: плоские темные полосы с собственным монохромным набором значков, плюс кнопки карты мира, списка друзей, поиска группы, магазина и связки ключей.",
    ["The experience bar width now adjusts in single steps."] = "Ширина панели опыта теперь настраивается с шагом в единицу.",
    ["Visibility conditions, colour modes with gradient, background and border colours, smooth value changes, hash marks and threshold colouring."] = "Условия видимости, режимы цвета с градиентом, цвета фона и каймы, плавные изменения значений, деления и окраска по порогам.",
    ["Character sheet stats panel no longer bleeds into other tabs; loadout sidebar aligns with the modern character sheet."] = "Панель характеристик окна персонажа больше не залезает на другие вкладки; боковая панель наборов экипировки выравнивается по современному окну персонажа.",
    ["Arena points calculator panel and button wear the addon look and dock beside the character sheet."] = "Панель и кнопка калькулятора очков арены оформлены в стиле аддона и пристыкованы рядом с окном персонажа.",
    ["The Escape menu now wears the dark addon look — flat buttons, accent title — and gains a VuloClassicUI button that opens the options window. Both have their own toggles under General."] = "Меню Escape теперь оформлено в темном стиле аддона — плоские кнопки, акцентный заголовок — и получает кнопку VuloClassicUI, открывающую окно настроек. У обоих есть собственные переключатели в разделе «Общее».",
    ["The add friend dialog is skinned to match: dark panel, accent headline, dark input field and flat buttons."] = "Диалог добавления друга оформлен в том же стиле: темная панель, акцентный заголовок, темное поле ввода и плоские кнопки.",
    ["Guild roster column header hover and click no longer stick out past the flat header row."] = "Наведение и щелчок на заголовках столбцов состава гильдии больше не выступают за плоскую строку заголовков.",
    ["The combat log filter bar now shares the exact width and height of the chat tab row, flush with the panel edge."] = "Панель фильтров журнала боя теперь имеет точно ту же ширину и высоту, что и строка вкладок чата, вплотную к краю панели.",
    ["After an update, a pulsing dot on the \"Patch Notes\" entry points at the new notes until you open them once — account wide, per version."] = "После обновления пульсирующая точка на пункте «Список изменений» указывает на новые заметки, пока вы не откроете их один раз — на весь аккаунт, для каждой версии.",
    ["With the Modern style, the equipment set sidebar now docks to the right of the stats panel at exactly the window's height, instead of overlapping it. Switching styles with the window open moves it immediately."] = "В стиле Modern боковая панель комплектов экипировки теперь пристыковывается справа от панели характеристик точно по высоте окна, а не перекрывает ее. Смена стиля при открытом окне перемещает ее сразу.",
    ["Micro menu buttons that the game hides situationally are shown again, so the row no longer has a gap."] = "Кнопки микроменю, которые игра скрывает в отдельных ситуациях, снова показываются, поэтому в ряду больше нет пропуска.",
    ["The default nameplate no longer shows through as a faint transparent bar under the custom plate — it is now hidden outright and kept hidden while the custom plate is active."] = "Стандартный индикатор здоровья больше не просвечивает бледной прозрачной полосой под своим индикатором — теперь он полностью скрыт и остается скрытым, пока активен свой индикатор.",
    ["All micro menu buttons open their windows again — the emptied default micro menu shell was invisibly swallowing clicks on the relocated buttons."] = "Все кнопки микроменю снова открывают свои окна — опустевшая стандартная оболочка микроменю незаметно проглатывала щелчки по перемещенным кнопкам.",
    ["Fixed a blocked-action error when the stance bar updated during combat; stance button visibility now only changes out of combat, while icon tint, cooldown and the active marker keep updating live."] = "Исправлена ошибка заблокированного действия при обновлении панели стоек в бою; видимость кнопок стоек теперь меняется только вне боя, а окраска значков, восстановление и отметка активной стойки продолжают обновляться сразу.",
    ["An Action Bars module puts every action bar on its own movable frame — action bars 1 to 5, the stance bar and the pet bar — each placed and scaled in Edit Mode and configured on its own."] = "Модуль «Панели команд» помещает каждую панель команд на собственную перемещаемую рамку — панели команд с 1 по 5, панель стоек и панель питомца — каждая размещается и масштабируется в Режиме редактирования и настраивается отдельно.",
    ["The main bar pages correctly with druid, rogue, warrior and priest forms, and your keybinds keep working on every bar, with the key shown on the buttons."] = "Основная панель правильно перелистывается при обликах и стойках друида, разбойника, воина и жреца, а ваши привязки клавиш продолжают работать на каждой панели, и клавиша показывается на кнопках.",
    ["Per bar: visibility (always, mouseover, in or out of combat), opacity, icon size, buttons per row, spacing, vertical layout, reverse order, and hiding the keybind or macro text — with adjustable text sizes for keybind, macro, count and cooldown numbers."] = "Для каждой панели: видимость (всегда, при наведении, в бою или вне боя), прозрачность, размер значков, число кнопок в ряду, отступы, вертикальное расположение, обратный порядок и скрытие текста привязок клавиш или макросов — с настраиваемыми размерами текста для привязок клавиш, макросов, количества и чисел восстановления.",
    ["Empty slots can be hidden and reappear automatically while you drag an ability onto the bar, and a bar can be made click-through."] = "Пустые ячейки можно скрыть — они автоматически появляются снова, пока вы перетаскиваете способность на панель, — а панель можно сделать прозрачной для щелчков.",
    ["Cooldown and look settings for all bars: cooldown sweep darkness, desaturating icons on cooldown, colouring icons while the target is out of range, and hiding button tooltips always or only in combat."] = "Настройки восстановления и внешнего вида для всех панелей: затемнение развертки восстановления, обесцвечивание значков во время восстановления, окраска значков, пока цель вне дальности, и скрытие подсказок кнопок всегда или только в бою.",
    ["An own experience bar with adjustable width, height and colour, rested overlay and progress text — it replaces the default bar while enabled and hides at the level cap."] = "Собственная панель опыта с настраиваемой шириной, высотой и цветом, наложением отдыха и текстом прогресса — пока она включена, она заменяет стандартную панель и скрывается на максимальном уровне.",
    ["The micro menu, the bag bar and the performance bar sit on movable holders, and each of them can be hidden — as can the default experience bar."] = "Микроменю, панель сумок и панель производительности находятся на перемещаемых держателях, и каждую из них можно скрыть — как и стандартную панель опыта.",
    ["Off by default: the standard bars stay untouched until you enable the module, and disabling hands everything back (a reload fully restores the default bars)."] = "По умолчанию выключено: стандартные панели остаются нетронутыми, пока вы не включите модуль, а отключение возвращает все обратно (перезагрузка интерфейса полностью восстанавливает стандартные панели).",
    ["The dark button skin now also covers the new action-bar buttons."] = "Темное оформление кнопок теперь также охватывает новые кнопки панелей команд.",
    ["A custom Nameplates module draws its own health bar, cast bar, name and health text over enemy and NPC nameplates — fully configurable, with a live preview that updates as you change each option."] = "Свой модуль «Индикаторы здоровья» рисует собственную полосу здоровья, полосу заклинания, имя и текст здоровья поверх индикаторов здоровья врагов и NPC — все полностью настраивается, с живым предпросмотром, который обновляется при изменении каждой опции.",
    ["Health bar with your choice of texture, width, height, background, and a border drawn as thin lines or a texture, all in your own colours."] = "Полоса здоровья с текстурой на ваш выбор, шириной, высотой, фоном и каймой в виде тонких линий или текстуры — все в ваших собственных цветах.",
    ["Colouring by reaction (hostile, neutral, friendly, tapped) and by class for players, plus role-based threat colouring for tanks and damage dealers."] = "Окраска по реакции (враждебные, нейтральные, дружественные, перехваченные другими) и по классу для игроков, плюс окраска по угрозе с учетом роли для танков и бойцов.",
    ["Target and focus highlight rings, and an optional fade for plates that are not your target."] = "Кольца подсветки цели и фокуса, а также необязательное затемнение индикаторов, которые не являются вашей целью.",
    ["Cast bar with spell icon, spell name, and a separate colour for casts that cannot be interrupted."] = "Полоса заклинания со значком заклинания, названием заклинания и отдельным цветом для заклинаний, которые нельзя прервать.",
    ["Aura rows: your debuffs (or all of them), enemy buffs, and a separate prominent row for crowd control such as Polymorph, Fear and Sap. A glow marks enemy buffs you can steal or dispel."] = "Ряды аур: ваши отрицательные эффекты (или все), положительные эффекты врагов и отдельный заметный ряд для контроля, такого как «Превращение», «Страх» и «Ошеломление». Свечение отмечает эффекты врагов, которые вы можете украсть или рассеять.",
    ["Combo point pips on your target for Rogues and Druids in cat form."] = "Метки очков серии приемов на вашей цели для разбойников и друидов в облике кошки.",
    ["Raid target markers (skull, cross, and the rest) with adjustable size and position."] = "Метки рейдовых целей (череп, крест и остальные) с настраиваемым размером и положением.",
    ["Friendly plates can show name only, the full plate, or nothing — set separately for players and NPCs — and can show a friendly NPC's subtitle under its name."] = "Дружественные индикаторы могут показывать только имя, полный индикатор или ничего — отдельно для игроков и NPC — и могут показывать подпись дружественного NPC под его именем.",
    ["A single \"Dark Skin\" module now covers the dark action-button and WeakAuras skin plus the optional Dark Mode that darkens Blizzard's default frames — those used to be two separate modules. Your existing settings carry over."] = "Единый модуль «Dark Skin» теперь охватывает темное оформление кнопок команд и WeakAuras, а также необязательный темный режим, затемняющий стандартные рамки Blizzard, — раньше это были два отдельных модуля. Ваши существующие настройки переносятся.",
    ["The reskin modules (skins, character panel, chat, friends list, minimap) are now one tabbed entry, matching how the other groups are already organised."] = "Модули оформления (оформление аддонов, панель персонажа, чат, список друзей, миникарта) теперь объединены в одну запись с вкладками, как уже организованы остальные группы.",
    ["Consolidated groups now list their modules as a vertical, icon-labelled column instead of a wrapping row of tabs — easier to scan when there are many."] = "Объединенные группы теперь показывают свои модули вертикальной колонкой со значками и подписями вместо переносимого ряда вкладок — так проще ориентироваться, когда их много.",
    ["A \"Patch Notes\" page under Overview shows every version's changes right in the game."] = "Страница «Список изменений» в разделе «Обзор» показывает изменения каждой версии прямо в игре.",
    ["Cleaner tab names for a few tools: Training, Leisten-Profile, Apexis-Minispiel, Gruppensuche."] = "Более аккуратные названия вкладок у нескольких инструментов: Training, Leisten-Profile, Apexis-Minispiel, Gruppensuche.",
    ["The target-frame extras and the elite player-frame border are now a single module called \"Player & Target Frame\". Your existing settings and per-character on and off state carry over automatically."] = "Дополнения рамки цели и элитная кайма рамки игрока теперь объединены в один модуль под названием «Player & Target Frame». Ваши существующие настройки и включение для каждого персонажа переносятся автоматически.",
    ["Settings now default to a separate profile per class, so what you set on one class no longer changes another. Your current settings are copied into each class profile, and you can still share or pin profiles as before."] = "Настройки теперь по умолчанию используют отдельный профиль для каждого класса, поэтому настроенное на одном классе больше не меняет другой. Ваши текущие настройки копируются в каждый классовый профиль, а делиться профилями и закреплять их можно, как и раньше.",
    ["Scrolling messages that fire at the same moment now stack with a gap instead of overlapping."] = "Бегущие сообщения, появляющиеся в один и тот же момент, теперь выстраиваются с отступом, а не перекрываются.",
    ["Fixed an error that could appear when combat started while your line was cast. The sound and interact settings now restore after combat ends instead."] = "Исправлена ошибка, которая могла возникать, если бой начинался при заброшенной удочке. Настройки звука и взаимодействия теперь восстанавливаются после окончания боя.",
    ["Lighter cast bar time text, cooldown bars that batch their refreshes during busy moments, a cheaper combat-log check for the cooldown pulse, and a lighter minimap hover check."] = "Более легкий текст времени на полосе заклинания, полосы восстановления, объединяющие свои обновления в напряженные моменты, более дешевая проверка журнала боя для пульсации восстановления и облегченная проверка наведения на миникарту.",
    ["The spell stats are ordered spell power, healing, spell crit, then spell hit."] = "Характеристики заклинаний упорядочены так: сила заклинаний, исцеление, критический удар заклинаний, затем меткость заклинаний.",
    ["The Fishing and Mail tabs now read \"Angeln\" and \"Post\"."] = "Вкладки рыбной ловли и почты теперь называются «Angeln» и «Post».",
    ["A style dropdown at the top of the module options. Classic+ keeps the current look; Modern is a new dark, single-window style."] = "Выпадающий список выбора стиля вверху настроек модуля. Classic+ сохраняет текущий вид; Modern — новый темный стиль в едином окне.",
    ["Modern reskins the whole character window dark with an accent border and a stats panel on the right: a big equipped item level, then collapsible categories — attributes, melee, spell, defense and resistances — with per-stat hover breakdowns and mouse-wheel scrolling."] = "Modern оформляет все окно персонажа в темном стиле с акцентной каймой и панелью характеристик справа: крупный уровень надетых предметов, затем сворачиваемые категории — атрибуты, ближний бой, заклинания, защита и сопротивления — с разбором каждой характеристики при наведении и прокруткой колесом мыши.",
    ["Under Modern the built-in stats, resistance icons and the model rotate arrows are hidden, and the reputation, skills and player-versus-player sub-tabs plus the bottom tabs are skinned to match. Everything switches back to Classic+ live, and adapts per client (rating stats only where they exist)."] = "В стиле Modern встроенные характеристики, значки сопротивлений и стрелки поворота модели скрыты, а подвкладки репутации, навыков и PvP, как и нижние вкладки, оформлены в том же стиле. Все переключается обратно на Classic+ сразу и подстраивается под клиент (характеристики рейтинга — только там, где они есть).",
    ["Dark skin for a world-map options window, with its own on and off switch in the Addon Skins options."] = "Темное оформление окна настроек карты мира с собственным переключателем в настройках «Оформление аддонов».",
    ["The clock now sits on the same line as the date and zone instead of floating higher."] = "Часы теперь находятся на одной строке с датой и зоной, а не выше.",
    ["Dark skin for a loot-distribution addon — its award and roll windows, its settings and overview windows, and the two always-visible roll and bid bars get the house panel, accent border and flat close button."] = "Темное оформление аддона распределения добычи — его окна наград и розыгрыша, окна настроек и обзора, а также две всегда видимые полосы розыгрыша и ставок получают фирменную панель, акцентную кайму и плоскую кнопку закрытия.",
    ["Dark skin for an attunement tracker — the main window and its buttons match the dark look; the colored status rows stay as they are so the state colors remain readable."] = "Темное оформление отслеживания допусков — главное окно и его кнопки соответствуют темному виду; цветные строки состояния остаются как есть, чтобы цвета состояний были читаемыми.",
    ["Both are separate on and off switches in the Addon Skins options, next to the others."] = "Оба имеют отдельные переключатели в настройках «Оформление аддонов», рядом с остальными.",
    ["Fixed: an expanded set sometimes would not collapse on the second click of its arrow. The arrow is also easier to hit now."] = "Исправлено: развернутый комплект иногда не сворачивался при втором щелчке по его стрелке. В стрелку теперь также проще попасть.",
    ["The slot flyout can now equip not-yet-bound items too — with the game's own \"this will bind to you\" confirmation before it soulbinds."] = "Выпадающая полоска ячейки теперь может надевать и еще не привязанные предметы — с собственным подтверждением игры «предмет станет персональным» перед привязкой.",
    ["Item levels in links now only show on uncommon (green) and better gear — grey and white trash no longer gets a number."] = "Уровни предметов в ссылках теперь показываются только на необычной (зеленой) и лучшей экипировке — серый и белый хлам больше не получает число.",
    ["No double number when another loot addon already tagged the item with its item level."] = "Больше нет двойного числа, когда другой аддон добычи уже пометил предмет его уровнем.",
    ["The date now shows next to the clock in the zone panel — click it to open the calendar, hover for the full date. Optional in the minimap settings."] = "Дата теперь показывается рядом с часами на панели зоны — нажмите на нее, чтобы открыть календарь, наведите для полной даты. Опционально в настройках миникарты.",
    ["The zone panel is a touch wider so the zone name, clock and date sit more comfortably."] = "Панель зоны стала немного шире, чтобы название зоны, часы и дата размещались свободнее.",
    ["Hover an equipment slot in the character window for a compact flyout of matching items from your bags — click one to equip it. The modifier-click picker is still there for a larger, pinnable window."] = "Наведите на ячейку экипировки в окне персонажа, чтобы увидеть компактную выпадающую полоску подходящих предметов из ваших сумок — нажмите на предмет, чтобы надеть его. Выбор по щелчку с модификатором по-прежнему доступен как большее закрепляемое окно.",
    ["Item levels on gear are now tinted in the item's quality color, matching the rest of the window (toggle in the options)."] = "Уровни предметов на экипировке теперь окрашены в цвет качества предмета, как и остальное окно (переключатель в настройках).",
    ["Section headers gained a thin divider line and a collapse control — click a category header to fold it away. The state is remembered per category."] = "Заголовки разделов получили тонкую разделительную линию и элемент сворачивания — нажмите на заголовок категории, чтобы свернуть ее. Состояние запоминается для каждой категории.",
    ["The window title now shows the used and total item count."] = "Заголовок окна теперь показывает число занятых и общее число ячеек.",
    ["Theme color — pick the accent color in the global settings (presets or your own). Everything purple follows it, saved per profile."] = "Цвет темы — выберите акцентный цвет в общих настройках (готовые варианты или свой). Все фиолетовые элементы следуют за ним; сохраняется в профиле.",
    ["Pin a profile to a single character; at login it beats the class assignment and the account-wide selection."] = "Закрепите профиль за одним персонажем; при входе он имеет приоритет над назначением по классу и выбором на весь аккаунт.",
    ["Track your own debuffs on the target, or set up a missing-buff reminder group (icon shows while the buff is absent)."] = "Отслеживайте свои отрицательные эффекты на цели или настройте группу напоминаний об отсутствующем эффекте (значок показывается, пока эффекта нет).",
    ["Icons tint blue when you are out of mana and red when the target is out of range; ready-only groups now pack without gaps."] = "Значки окрашиваются синим, когда у вас закончилась мана, и красным, когда цель вне дальности; группы «только готовое» теперь располагаются без пропусков.",
    ["Auto-track your equipped trinkets, duplicate a whole group, and optional hover tooltips."] = "Автоматическое отслеживание надетых аксессуаров, дублирование целой группы и необязательные подсказки при наведении.",
    ["Dark skin for the guild & communities window — flat tabs, list cards, roster and chat panels."] = "Темное оформление окна гильдии и сообществ — плоские вкладки, карточки списков, панели состава и чата.",
    ["Pushback readout, a latency window on casts (the spell-queue moment), a crafting-series counter (e.g. 3/20), timer format options, accent/class fill colors and smoother fill on time jumps."] = "Индикация сбива произнесения, окно задержки на заклинаниях (момент очереди заклинаний), счетчик серии создания предметов (например, 3/20), варианты формата таймера, акцентный или классовый цвет заполнения и более плавное заполнение при скачках времени.",
    ["Reworked with inline spell icons and bracketed spell names; separate purge, incoming-dispel, buff-given/received and spell-reflect messages, with anti-spam throttling."] = "Переработано со встроенными значками заклинаний и названиями заклинаний в скобках; отдельные сообщения о снятии положительных эффектов, входящем рассеивании, наложенных и полученных эффектах и отражении заклинаний, с защитой от спама.",
    ["Death announcements for group members with class-colored names."] = "Объявления о смерти участников группы с именами в цветах классов.",
    ["A per-character snapshot of your bank contents, viewable anywhere from the bag window — with tooltips and smart search."] = "Снимок содержимого банка для каждого персонажа, доступный откуда угодно из окна сумок — с подсказками и умным поиском.",
    ["A dark guild bank window with tabs, search, a money log, deposit/withdraw and engine-based sorting."] = "Темное окно банка гильдии с вкладками, поиском, журналом золота, внесением и снятием и сортировкой на основе движка.",
    ["Full dark reskin of the friends window with class crests, row layout, tabs and a battletag pill."] = "Полное темное оформление окна друзей с гербами классов, новым видом строк, вкладками и плашкой BattleTag.",
    ["Addon Skins module — matches supported third-party windows to the dark look, including a quest tracker with accent headers."] = "Модуль «Оформление аддонов» — приводит окна поддерживаемых сторонних аддонов к темному виду, включая отслеживание заданий с акцентными заголовками.",
    ["Smart search keywords (quality, type, item level) that also search an open bank and guild bank."] = "Ключевые слова умного поиска (качество, тип, уровень предмета), которые также ищут в открытом банке и банке гильдии.",
    ["Bind-on-equip and junk markers, keyring separation, and a fixed-slot OneBag layout."] = "Метки предметов, персональных при надевании, и хлама, отделение связки ключей и раскладка OneBag с фиксированными ячейками.",
    ["Availability markers, set-preview tooltips, true partial sets, and an item-level/set warning in the disenchant queue."] = "Метки доступности, подсказки с предпросмотром комплектов, настоящие частичные комплекты и предупреждение об уровне предмета и комплекте в очереди распыления.",
    ["Rebuilt sort engine (bags, bank and guild bank) that keeps materials and gear apart."] = "Переработанный движок сортировки (сумки, банк и банк гильдии), который держит материалы и экипировку раздельно.",
    ["Minimap and totem-bar improvements, plus framework hardening for the current clients."] = "Улучшения миникарты и панели тотемов, а также укрепление основы для текущих клиентов.",
    ["A single unified inventory window: search, sort, categories, custom groups, pinned & recent items, keyring, quick-drop, item levels and quality borders."] = "Единое окно инвентаря: поиск, сортировка, категории, свои группы, закрепленные и недавние предметы, связка ключей, быстрый сброс, уровни предметов и каймы качества.",
    ["A new bank window with slot purchasing."] = "Новое окно банка с покупкой ячеек.",
    ["Friends counter in the chat, a gold overview tooltip, and taint-free Edit Mode movers."] = "Счетчик друзей в чате, подсказка с обзором золота и перемещение окон в Режиме редактирования без taint.",
    ["Chat module polish and localization fixes."] = "Доработка модуля чата и исправления локализации.",
    ["A reworked chat: timestamps, class-colored names, clickable links, short channel names, a dark panel with an icon sidebar, idle fade and history that survives a reload. Every part is optional."] = "Переработанный чат: отметки времени, имена в цветах классов, кликабельные ссылки, короткие названия каналов, темная панель с боковой панелью значков, затемнение при бездействии и история, которая переживает перезагрузку интерфейса. Каждая часть необязательна.",
    ["Per-frame free-move and an anchor toggle, with panel polish."] = "Свободное перемещение каждого окна и переключатель привязки, а также доработка панели.",
    ["Dark border on the action bars; fixed a compat-frame taint issue."] = "Темная кайма на панелях команд; исправлена проблема taint в рамке совместимости.",
    ["A dark-mode module, plus German localization fixes."] = "Модуль темного режима, а также исправления немецкой локализации.",
    ["NEW:"] = "НОВОЕ:",
    ["A single unified inventory window: all bags in one grid, with quality borders, counts, cooldowns, money and free slots. Movable and scalable."] = "Единое окно инвентаря: все сумки в одной сетке, с каймами качества, количеством, восстановлением, золотом и свободными ячейками. Перемещается и масштабируется.",
    ["Fixes stuck inspect bugs (no player inspect possible after a faulty close/timeout). Auto-reset after a timeout, auto-retry when the window stays empty, cleanup when InspectFrame closes + /inspectreset slash command."] = "Исправляет зависший осмотр (после сбойного закрытия или тайм-аута осмотр игроков становится невозможным). Автосброс после тайм-аута, автоповтор, если окно остается пустым, очистка при закрытии InspectFrame + команда /inspectreset.",
    ["A modern minimap: round with a clean dark ring and accent line, zone text and clock in a slim panel, mouse-wheel zoom, movable and scalable. Optionally hides other addons' buttons until mouseover."] = "Современная миникарта: круглая, с чистым темным кольцом и акцентной линией, текст зоны и часы на тонкой панели, масштабирование колесом мыши, перемещается и масштабируется. Опционально скрывает кнопки других аддонов до наведения мыши.",
    ["Custom enemy & NPC nameplates with a live preview: health bar, cast bar, name and health text, reaction / class colours, target highlight and threat colouring."] = "Свои индикаторы здоровья врагов и NPC с живым предпросмотром: полоса здоровья, полоса заклинания, имя и текст здоровья, цвета реакции и класса, подсветка цели и окраска по угрозе.",
    ["Hover an equipment slot for a compact flyout of compatible bag items, or modifier-click for a larger picker. Click an item to equip it."] = "Наведите на ячейку экипировки, чтобы увидеть компактную выпадающую полоску подходящих предметов из сумок, или нажмите с модификатором для большего окна выбора. Нажмите на предмет, чтобы надеть его.",
    ["Move every VuloUI window and Blizzard's default frames in one editor."] = "Перемещайте каждое окно VuloUI и стандартные рамки Blizzard в одном редакторе.",
    ["One-key fishing: one key casts, reels and applies a lure, and auto-loots your catch."] = "Рыбалка одной клавишей: одна клавиша забрасывает, подсекает и наносит приманку, а также автоматически собирает улов.",
    ["Scans chat for people forming groups and lists them by Classic/TBC instance in a window (/vlfg or the minimap button)."] = "Сканирует чат в поисках игроков, собирающих группы, и показывает их в окне по подземельям Classic/TBC (/vlfg или кнопка на миникарте).",
    ["Adds an 'Open All' button to your mailbox that collects every attachment and coin in one click."] = "Добавляет в почтовый ящик кнопку «Открыть все», которая собирает все вложения и деньги одним щелчком.",
    ["Top"] = "Сверху",
    ["Bottom"] = "Снизу",
    ["Top-Left"] = "Сверху слева",
    ["Top-Right"] = "Сверху справа",
    ["Bottom-Left"] = "Снизу слева",
    ["Bottom-Right"] = "Снизу справа",
    ["Trinkets: Cleared all ignored/hidden trinkets."] = "Trinkets: список игнорируемых и скрытых аксессуаров очищен.",
    ["Trinkets usage:"] = "Использование Trinkets:",
    ["/trinket or /Trinkets : toggle the window"] = "/trinket or /Trinkets : показать или скрыть окно",
    ["/trinket reset : reset all settings"] = "/trinket reset : сбросить все настройки",
    ["/trinket clear : clear all ignored/hidden trinkets"] = "/trinket clear : очистить все игнорируемые и скрытые аксессуары",
    ["/trinket opt : summon options window"] = "/trinket opt : открыть окно настроек",
    ["/trinket lock|unlock : toggles window lock"] = "/trinket lock|unlock : закрепить или открепить окно",
    ["/trinket scale main|menu (number) : sets an exact scale"] = "/trinket scale main|menu (number) : задать точный масштаб",
    ["/trinket load top|bottom profilename : loads a profile to top or bottom trinket"] = "/trinket load top|bottom profilename : загрузить профиль в верхний или нижний аксессуар",
    ["Are you sure you want to reset Trinkets to default state and reload the UI?"] = "Вы уверены, что хотите сбросить Trinkets к состоянию по умолчанию и перезагрузить интерфейс?",
    ["Queued: %s"] = "В очереди: %s",
    ["Priority"] = "Приоритет",
    ["Pause Queue"] = "Приостановить очередь",
    ["Parameter must be 0 for top trinket or 1 for bottom."] = "Параметр должен быть 0 для верхнего аксессуара или 1 для нижнего.",
    ["No profiles saved yet."] = "Профили пока не сохранены.",
    -- Patch notes 1.37.1
    ["Visuals"] = "Внешний вид",
    ["The language option under General now actually applies. It silently never took effect — the addon read the client language before your saved choice was loaded. After a /reload every label, dropdown and popup follows your choice."] = "Выбор языка в разделе «Общее» теперь действительно применяется. Он незаметно никогда не срабатывал: аддон считывал язык клиента до загрузки сохранённого выбора. После /reload все надписи, выпадающие списки и окна следуют вашему выбору.",
    ["The Patch Notes page is translated into all languages, including every past version."] = "Страница заметок к обновлению переведена на все языки, включая все прошлые версии.",
    ["The trinket panel, its queue window and the /trinket help are translated too."] = "Панель аксессуаров, её окно очереди и справка /trinket тоже переведены.",
    ["German: sixteen duplicated translations cleaned up, five of which contradicted each other."] = "Немецкий: убраны шестнадцать дублирующихся переводов, пять из них противоречили друг другу.",
    ["Third pass over the busiest code paths: nameplate auras scan once instead of four times, combat-log and aura events skip a safety wrapper, timer texts only redraw when the shown number changes, and several background listeners now sleep while their feature is off or hidden. Less stutter in raids and arenas."] = "Третий проход по самым нагруженным участкам кода: ауры на индикаторах здоровья сканируются один раз вместо четырёх, события журнала боя и аур обходятся без защитной обёртки, тексты таймеров перерисовываются только при смене показанного числа, а несколько фоновых слушателей спят, пока их функция выключена или скрыта. Меньше подтормаживаний в рейдах и на аренах.",
    ["The frames can be turned off again without leftovers."] = "Окна снова можно отключить без остатков.",
    ["An interrupted enemy cast now shows INTERRUPTED briefly — it used to vanish the same instant."] = "Прерванное заклинание противника теперь ненадолго показывает ПРЕРВАНО — раньше оно исчезало в тот же миг.",
    ["Diminishing-returns icons clean up correctly after toggling the tracker mid-arena."] = "Значки убывающей отдачи корректно очищаются после переключения отслеживания посреди арены.",
    ["Seven working settings that were invisible in the options are shown again, and several switches that did nothing are wired up."] = "Семь рабочих настроек, невидимых в опциях, снова отображаются, а несколько бездействовавших переключателей теперь подключены.",
    ["Modules tidy up after themselves when disabled: totem range dimming, the inspect window, queue timer, quest log and font bars no longer leave stale pieces behind."] = "Модули убирают за собой при отключении: затемнение тотемов вне досягаемости, окно осмотра, таймер очереди, журнал заданий и полосы шрифтов больше не оставляют устаревших частей.",
    ["Three modules got their own sidebar icons instead of the placeholder, and Reminders got a nicer bell."] = "Три модуля получили собственные значки в боковой панели вместо заглушки, а «Напоминания» — колокольчик покрасивее.",
    -- Bags: quest starter marker
    ["Quest starter marker (!)"] = "Метка начала задания (!)",
    ["Overlays a yellow exclamation mark on items that start a quest you have not accepted yet."] = "Накладывает жёлтый восклицательный знак на предметы, начинающие ещё не принятое задание.",
    -- Options page build failure
    ["|cffff5555Options page '%s' failed to build:|r %s"] = "|cffff5555Не удалось построить страницу настроек «%s»:|r %s",
    ["|cffff5555This page could not be built. /reload, and report it if it persists.|r"] = "|cffff5555Не удалось построить эту страницу. Выполните /reload и сообщите, если это повторится.|r",
    ["|cff888888%.2f ms/frame |cff666666(%.1f%% of ours, peak %.1f ms)|r|r"] = "|cff888888%.2f мс/кадр |cff666666(%.1f%% наши, пик %.1f мс)|r|r",
    ["|cffaaaaaaThe header shows how much frame time VuloClassicUI costs. Your client measures this on its own, all the time — no setting and no reload needed.|r"] = "|cffaaaaaaВ заголовке показано, сколько кадрового времени тратит VuloClassicUI. Клиент измеряет это сам и постоянно — без настроек и перезагрузки.|r",
    -- Patch notes 1.37.2
    ["Classic Era, Hardcore and Season of Discovery"] = "Classic Era, Hardcore и Season of Discovery",
    ["Under the hood"] = "Под капотом",
    ["The addon loads again without ticking \"Load out of date AddOns\". Blizzard's July interface update moved these realms to a new version number."] = "Аддон снова загружается без галочки «Загружать устаревшие аддоны». Июльское обновление интерфейса от Blizzard перевело эти миры на новый номер версии.",
    ["Fixed a crash that switched the whole Class Trainer page off on Season of Discovery: one ability the realm does not know took the entire module down with it."] = "Исправлен сбой, отключавший всю страницу учителя класса в Season of Discovery: одна-единственная способность, неизвестная миру, роняла весь модуль.",
    ["The elite border on your player frame sits correctly again. It was placed against the old frame layout, which that same update replaced."] = "Элитная рамка вокруг окна персонажа снова на своём месте. Она выставлялась по старой раскладке окна, которую заменило то же самое обновление.",
    ["Fixed a rare error storm at the end of a fight. Cleanup work in nineteen files could be skipped and the chat filled with error lines."] = "Исправлен редкий поток ошибок в конце боя. Уборка в девятнадцати файлах могла пропускаться, а чат заполнялся строками ошибок.",
    ["Combat log features (swing timer, cooldown pulse, combat text, arena tracker, nameplates, mana display) no longer depend on a setting a player can switch off."] = "Возможности на основе журнала боя (таймер удара, пульс восстановления, боевые тексты, отслеживание арены, индикаторы здоровья, показ маны) больше не зависят от настройки, которую можно выключить.",
    ["An interrupted enemy cast now really shows INTERRUPTED for a moment."] = "Прерванное заклинание противника теперь действительно показывает прерывание на мгновение.",
    ["Items that start a quest you have not accepted yet are marked with a yellow exclamation mark, in bags, bank and keyring."] = "Предметы, начинающие ещё не принятое задание, помечаются жёлтым восклицательным знаком — в сумках, банке и связке ключей.",
    ["Seven of the eight shipped translations no longer build their lookup table at all. Only the language you actually read is assembled, which frees about a megabyte on every login."] = "Семь из восьми поставляемых переводов больше вообще не строят свою таблицу. Собирается только тот язык, который вы действительно читаете, что освобождает около мегабайта при каждом входе.",
    ["Edit Mode: three background drivers no longer run permanently, dragging a window allocates far less, and finding a window is a direct lookup instead of a search."] = "Режим редактирования: три фоновых механизма больше не работают постоянно, перетаскивание окна создаёт заметно меньше мусора, а поиск окна стал прямым обращением вместо перебора.",
    ["Disabling a module now detaches it completely — several used to leave listeners running for the rest of the session."] = "Отключённый модуль теперь отсоединяется полностью: некоторые оставляли обработчики работать до конца сеанса.",
    ["The performance readout in the header uses your client's own always-on measurement, so it needs no setting and no reload."] = "Показатель производительности в заголовке использует постоянно работающее измерение вашего клиента, поэтому ему не нужны ни настройка, ни перезагрузка.",
    -- Patch notes 1.37.2
    -- Built-in profiler
    ["Nothing measured yet. Play for a bit, then read it again."] = "Пока ничего не измерено. Поиграйте немного и прочитайте снова.",
    ["Measured over %.1f s -- %.1f ms total, %.2f%% of it ours:"] = "Измерено за %.1f с: всего %.1f мс, из них %.2f%% наши:",
    ["Measurement off."] = "Измерение выключено.",
    ["Measurement reset."] = "Измерение сброшено.",
    ["Measurement on. Play, then type /vcuiprof again to read it."] = "Измерение включено. Поиграйте, затем снова введите /vcuiprof.",
    -- Patch notes 1.37.3
    ["Class Trainer page"] = "Страница учителя класса",
    ["Fixed the page being thrown away again a moment after you opened it, dropping you back on a class tab. The spell book resets its own page whenever your spells change, and our page sits past the last real tab, so it was always the one discarded. Most noticeable on Season of Discovery, where engraving changes spells constantly."] = "Исправлено: страница отбрасывалась через мгновение после открытия и возвращала вас на вкладку класса. Книга заклинаний сбрасывает собственную страницу при любом изменении заклинаний, а наша находится за последней настоящей вкладкой — поэтому отбрасывало всегда её. Заметнее всего в Season of Discovery, где нанесение рун меняет заклинания постоянно.",
    ["`/vcuiprof` measures how much frame time each part of the addon costs, then prints a list. It ships switched off and costs nothing while it is — the measuring code is only put in place when you turn it on. Type it once to start, once more to read."] = "`/vcuiprof` измеряет, сколько кадрового времени тратит каждая часть аддона, и выводит список. Он поставляется выключенным и в таком виде не стоит ничего: измеряющий код подставляется только при включении. Введите один раз, чтобы начать, и ещё раз, чтобы прочитать.",
    -- Patch notes 1.37.4
    ["Clicking a trinket button while that trinket slot is empty no longer throws an error. The game's own shortcut for \"use the item in slot N\" stopped tolerating an empty slot with July's interface update, so the button now takes a different route to the same action."] = "Щелчок по кнопке аксессуара при пустой ячейке больше не вызывает ошибку. Собственное сокращение игры «использовать предмет в ячейке N» перестало допускать пустую ячейку после июльского обновления интерфейса, поэтому кнопка теперь идёт к тому же действию другим путём.",
    ["Fixed a stutter of almost two frames every time you entered or left combat, if you use WeakAuras and have the WeakAuras skin switched on. Every combat change repainted every aura you have ever saved — including the ones not on screen — with a look that had not changed. Auras are now only repainted when the settings or their size actually changed. Measured: 28 ms down to under 2 ms. The skin itself is unchanged."] = "Исправлено подёргивание почти на два кадра при каждом входе в бой и выходе из него, если вы пользуетесь WeakAuras и включили наше оформление для WeakAuras. При каждой смене боя перерисовывались все когда-либо сохранённые ауры — включая те, которых нет на экране — с оформлением, которое не менялось. Теперь ауры перерисовываются только при реальном изменении настроек или размера. Измерено: с 28 мс до менее 2 мс. Само оформление не изменилось.",
    -- Patch notes 1.39.0
    ["Download"] = "Загрузка",
    ["Diminishing Returns Position – Put the DR row on either side of the frame, with its own X and Y offset"] = "Положение убывающей отдачи – Ряд можно поставить с любой стороны рамки, со своим смещением по X и Y",
    ["The DR row no longer lands on top of the trinket or racial icon. It used to hang at a fixed distance on the right edge, exactly where the side icon sits, so switching it on stacked the two. The new default clears it, and on the left edge the row grows outward instead of across the frame."] = "Ряд убывающей отдачи больше не ложится поверх значка аксессуара или расовой способности. Раньше он висел на жёстко заданном расстоянии от правого края, ровно там, где стоит боковой значок, поэтому при включении они накладывались друг на друга. Новое значение по умолчанию уводит ряд в сторону, а у левого края ряд растёт наружу, а не через рамку.",
    ["The trinket and racial icons sit further out from the enemy frame and are a little smaller, so the health and mana bars read as the middle of the frame instead of competing with an icon at each shoulder. Both are sliders, so your own values are kept."] = "Значки аксессуара и расовой способности расположены дальше от рамки противника и стали чуть меньше, так что полосы здоровья и маны читаются как середина рамки, а не соперничают со значком на каждом плече. Оба параметра — ползунки, поэтому ваши собственные значения сохраняются.",
    ["The addon folder no longer ships build tools and source files that no player needs. The licence files stay where they are."] = "В папке аддона больше нет инструментов сборки и исходных файлов, которые не нужны ни одному игроку. Файлы лицензий остаются на месте.",
    ["The release notes on the distribution pages are written in English now."] = "Примечания к версиям на страницах распространения теперь написаны на английском.",
    ["Six languages were missing seven texts that existed in German only. All nine are complete again."] = "В шести языках не хватало семи строк, которые существовали только на немецком. Все девять снова полны.",
    ["The keyword help for the item search was misleading in Chinese: it gave an English type name as the example, which a Chinese client would never have matched. The example is written in the reader's own language now."] = "Подсказка по ключевым словам в поиске предметов была неверной для китайского: в примере стояло английское название типа, которое китайский клиент никогда бы не нашёл. Теперь пример написан на языке читателя.",
    ["Seal Twist Helper – A swing bar with the twist window marked, plus the next sensible action"] = "Помощник по смене печатей – Полоса удара с отмеченным окном смены и следующее разумное действие",
    ["The bar counts down to your next auto attack with two marks: green is the last moment the second seal can still land, purple is how long a Judgement still fits in front of it. The next action is worked out live from your swing timer, the global cooldown and the seals actually on you — not from a fixed rotation. Crusader Strike is only suggested while there is room for it and the holding seal afterwards. Judgement deliberately gets none: it consumes the seal, and a wrong hint costs more there than no hint. Off by default."] = "Полоса отсчитывает время до следующей автоатаки и имеет две метки: зелёная — последний момент, когда вторая печать ещё успевает лечь, фиолетовая показывает, сколько времени перед ней ещё помещается Правосудие. Следующее действие рассчитывается вживую по вашему ритму ударов, общему времени восстановления и печатям, которые действительно на вас, — а не по заранее заданной ротации. Удар крестоносца предлагается только пока остаётся место для него и для удерживаемой печати. Правосудие намеренно остаётся без подсказки: оно расходует печать, и неверная подсказка обходится там дороже, чем её отсутствие. По умолчанию выключено.",
    -- Sidebar groups (QoL split, 1.40.0)
    ["Bags & Items"] = "Сумки и предметы",
    ["Chat & Social"] = "Чат и общение",
    ["Extras"] = "Разное",
    ["Tools"] = "Инструменты",
    -- Overview page
    ["peak %.1f ms"] = "пик %.1f мс",
    ["%.2f ms"] = "%.2f мс",
    ["%.1f MB"] = "%.1f МБ",
    ["%d KB"] = "%d КБ",
    ["%d of %d"] = "%d из %d",
    ["moved"] = "перемещено",
    ["Modules"] = "Модули",
    ["Frame time"] = "Время кадра",
    ["Memory"] = "Память",
    ["Windows"] = "Окна",
    ["%d modules are switched off."] = "Отключено модулей: %d.",
    ["The edit mode grid is switched on."] = "Сетка режима редактирования включена.",
    ["There are patch notes you have not read yet."] = "Есть непрочитанные примечания к версии.",
    ["What would you like to change?"] = "Что вы хотите настроить?",
    ["Worth knowing"] = "Полезно знать",
    ["Recently visited"] = "Недавно открытые",
    -- Talent overrides
    ["active"] = "активно",
    ["Talent Overrides"] = "Настройки по набору талантов",
    ["Talent group %d"] = "Набор талантов %d",
    ["Record changes for this talent group"] = "Запоминать изменения для этого набора",
    ["While this is on, every setting you change is remembered for this talent group and applied again whenever you switch back to it. Switch it off when you are done."] = "Пока это включено, каждая изменённая настройка запоминается для этого набора талантов и применяется снова при возврате к нему. Выключите, когда закончите.",
    ["Recording for %s"] = "Запись для %s",
    ["%d settings overridden"] = "Переопределено настроек: %d",
    ["Forget all overrides for this talent group"] = "Забыть все настройки этого набора",
    ["Overrides apply on their own when you switch talent groups. This client has no specialisations, so the dual talent system is the axis."] = "Настройки применяются сами при смене набора талантов. В этом клиенте нет специализаций, поэтому ось — двойная система талантов.",
    -- Override groups
    ["Talent group %d (%s)"] = "Набор талантов %d (%s)",
    ["Name for the new group"] = "Название новой группы",
    ["Editing as"] = "Редактируется как",
    ["Yourself"] = "Вы сами",
    ["Manage groups..."] = "Управление группами...",
    ["Owns the current talent group"] = "Действует для текущего набора талантов",
    ["Delete this group"] = "Удалить эту группу",
    ["No groups yet."] = "Групп пока нет.",
    -- Anchor points
    ["Centre"] = "По центру",
    ["Thin outline"] = "Тонкий контур",
    ["Bar Setups"] = "Наборы панелей",
    -- Patch notes 1.40.0
    ["Moved out of the sidebar into Global Settings, as its own tab beside Profiles. Your saved setups were kept."] = "Перенесено из боковой панели в Общие настройки, в собственную вкладку рядом с Профилями. Сохранённые наборы остались на месте.",
    ["They were stored once per class profile — seven copies of one macro library. Stored once now, which cut the settings file by a third. Identical copies are merged, ones that differ are kept side by side."] = "Они хранились по одному разу в каждом профиле класса — семь копий одной и той же библиотеки макросов. Теперь хранятся один раз, и файл настроек стал меньше на треть. Одинаковые копии объединяются, различающиеся сохраняются рядом.",
    ["The chat window no longer jumps back the moment you open the edit mode. Switching layouts re-anchors every window the game knows about, including ones we place ourselves."] = "Окно чата больше не отскакивает назад, как только открываешь режим редактирования. Смена раскладки заново привязывает все окна, известные игре, включая те, что расставляем мы сами.",
    ["A dropdown with a long entry no longer wraps into the row below it."] = "Выпадающее меню с длинной строкой больше не переносится на строку ниже.",
    ["The first page is a picture of your interface instead of a second sidebar: modules running, frame time and memory, windows you moved, pages you last visited."] = "Первая страница показывает состояние интерфейса вместо второй боковой панели: работающие модули, время кадра и память, перемещённые окна и последние открытые страницы.",
    ["Talent Overrides – Named groups hold their own value for individual settings and apply when you switch talent specs"] = "Переопределения талантов – Именованные группы хранят собственные значения отдельных настроек и применяются при смене набора талантов",
    ["A group can also name a situation — raid, dungeon, arena, battleground, in a group, alone. Anything you change while a group is active is recorded into it, and every overridden row is marked."] = "Группа может дополнительно указать ситуацию: рейд, подземелье, арена, поле боя, в группе, в одиночку. Всё, что меняешь при активной группе, записывается в неё, а каждая переопределённая строка помечается.",
    ["Sliders are one row like every other setting, their number can be typed into, and labels line up in a measured column across the page. A long translation no longer pushes a value box into the next column or a button off its card."] = "Ползунки занимают одну строку, как и любая другая настройка, их число можно ввести с клавиатуры, а подписи выровнены по измеренному столбцу на всю страницу. Длинный перевод больше не выталкивает поле значения в соседний столбец, а кнопку — за пределы карточки.",
    ["Every section starts closed, so a long page opens as a list of headings."] = "Каждый раздел открывается свёрнутым, поэтому длинная страница выглядит как список заголовков.",
    ["The automatic swap queue has controls again — order, delay and the stop marker, on the trinket page. They only ever existed in a window this addon hides."] = "У очереди автоматической смены снова есть управление: порядок, задержка и метка остановки на странице аксессуаров. Раньше они были только в окне, которое этот аддон скрывает.",
    ["Trinket icons show up again: on the buttons, on the queue marker, and on your worn trinkets right after login instead of only once you click them."] = "Значки аксессуаров снова на месте: на кнопках, на метке очереди и на надетых аксессуарах сразу после входа в игру, а не только после щелчка.",
    -- Befehlsregistratur
    ["%s has no handler yet — this is a bug, please report it."] = "%s пока не имеет обработчика — это ошибка, пожалуйста, сообщите о ней.",
    ["%s belongs to %s, which is switched off."] = "%s относится к %s, а этот модуль выключен.",
    ["|cff9b6cffCommands|r — %d in total. Grey ones belong to a module that is switched off."] = "|cff9b6cffКоманды|r — всего %d. Серые относятся к выключенному модулю.",
    ["%s is also claimed by another addon (%s) — one of the two wins."] = "%s также занята другим аддоном (%s) — сработает только одна из двух.",
    -- v1.40.0 nachgezogen
    ["|cffff5555Bar setups module not loaded.|r"] = "|cffff5555Модуль наборов панелей не загружен.|r",
    ["Bar setup '%s' saved."] = "Набор панелей '%s' сохранён.",
    ["Bar setup '%s' deleted."] = "Набор панелей '%s' удалён.",
    ["Not in combat — bars can't be changed while fighting."] = "Вне боя — панели нельзя менять во время боя.",
    ["Bar setup '%s' loaded: %d slots set, %d cleared, |cffff8800%d skipped|r (unknown spell / missing item or macro)."] = "Набор панелей '%s' загружен: %d ячеек заполнено, %d очищено, |cffff8800%d пропущено|r (неизвестное заклинание / отсутствует предмет или макрос).",
    ["Bar setup '%s' loaded: %d slots set, %d cleared."] = "Набор панелей '%s' загружен: %d ячеек заполнено, %d очищено.",
    ["on"] = "вкл",
    ["Overridden settings: %s"] = "Переопределённые настройки: %s",
    ["Situation"] = "Ситуация",
    ["Everywhere"] = "Везде",
    ["Raid instance"] = "Рейдовое подземелье",
    ["5-player instance"] = "Подземелье на 5 игроков",
    ["Battleground"] = "Поле боя",
    ["In a group"] = "В группе",
    ["Alone"] = "В одиночку",
    ["Applies only in this situation. Combined with a talent group, both have to be true - and that group then overrides one that names only the talent group."] = "Действует только в этой ситуации. Вместе с набором талантов должны выполняться оба условия — и такая группа тогда важнее той, что указывает только набор талантов.",
    ["Icon"] = "Значок",
    ["No icon"] = "Без значка",
    ["Shown in front of the group name in the menu and on the header button."] = "Показывается перед названием группы в меню и на кнопке заголовка.",
    ["Switch off to drop this one override. The setting then follows the profile again."] = "Выключение убирает только это переопределение. Настройка снова следует профилю.",
    ["Bar setups are now stored once for the whole account: %d kept, %d duplicates merged."] = "Наборы панелей теперь хранятся один раз на всю учётную запись: %d сохранено, %d дубликатов объединено.",
    ["Trinket window settings now live in this addon's own database."] = "Настройки окна аксессуаров теперь хранятся в собственной базе данных этого аддона.",
    ["Auto queue: top slot"] = "Автоочередь: верхняя ячейка",
    ["Auto queue: bottom slot"] = "Автоочередь: нижняя ячейка",
    ["Auto queue for this slot"] = "Автоочередь для этой ячейки",
    ["Same switch as alt-clicking the slot. While on, the queue swaps this trinket in combat, following the order below."] = "Тот же переключатель, что и alt-щелчок по ячейке. Когда включено, очередь меняет этот аксессуар в бою по порядку ниже.",
    ["Order"] = "Порядок",
    ["The queue works through this list from the top. Pick an entry to move it or to change its settings."] = "Очередь идёт по этому списку сверху вниз. Выбери запись, чтобы переместить её или изменить её настройки.",
    ["- empty -"] = "- пусто -",
    ["— queue stops here —"] = "— дальше замены нет —",
    ["Add from bags"] = "Добавить из сумок",
    ["Adds a trinket you are carrying to the end of this list."] = "Добавляет в конец этого списка аксессуар, который у тебя с собой.",
    ["Swap delay"] = "Задержка замены",
    ["Seconds this trinket stays equipped before the queue swaps it out again. 0 = no wait."] = "Сколько секунд этот аксессуар остаётся надетым, прежде чем очередь снова его сменит. 0 = без ожидания.",
    ["This trinket is swapped in ahead of the ones above it once it is ready."] = "Этот аксессуар надевается раньше тех, что выше, как только будет готов.",
    ["Pause while equipped"] = "Пауза, пока надет",
    ["While this trinket is worn the queue holds still - for a trinket whose effect you do not want cut short."] = "Пока этот аксессуар надет, очередь стоит — для аксессуара, эффект которого не стоит обрывать.",
    ["|cffaaaaaaTip: left click a slot to use the trinket, right click for the list. Alt-click arms the auto queue for that slot.|r"] = "|cffaaaaaaПодсказка: щелчок левой кнопкой по ячейке использует аксессуар, правой — открывает список. Alt-щелчок включает автоочередь для этой ячейки.|r",
    ["%d snapshot(s) had the same name but different contents and were kept under a new name."] = "%d снимок(ов) имели одинаковое имя при разном содержимом и сохранены под новым именем.",
    ["GAP"] = "ОТСТУП",
    ["Distance from that edge, in pixels. 0 is flush."] = "Расстояние до этого края, в пикселях. 0 — вплотную.",
    ["Docks this window to that side of the target and centres it there. 'Centered' does not move it - it only travels along. The gap is kept edge-to-edge, so it survives either window being resized."] = "Пристыковывает это окно к выбранной стороне целевого окна и центрирует его там. 'По центру' не двигает окно — оно только следует за целью. Отступ выдерживается от края до края, поэтому переживает изменение размера любого из окон.",
    ["waiting for a swing"] = "ожидание удара",
    ["  -  lag %.0fms"] = "  -  задержка %.0fмс",
    ["|cffaaaaaaHold Seal of Command, then cast the second seal in the last fraction of a second before your auto-attack: that swing carries both. The bar counts down to the swing, the |cff33ff66green zone|r is the twist window and the |cffb388ffpurple mark|r is the last moment a cast of the held seal still fits in front of it. Below level 64 the second seal is Righteousness; Blood and the Martyr replace it from there.|r"] = "|cffaaaaaaДержите Печать повеления и накладывайте вторую печать в последнюю долю секунды перед автоатакой: этот удар получит обе. Полоса отсчитывает время до удара, |cff33ff66зелёная зона|r — окно смены, а |cffb388ffфиолетовая метка|r — последний момент, когда накладывание удерживаемой печати ещё успевает перед ним. До 64-го уровня вторая печать — Печать праведности; дальше её сменяют Печать крови и Печать мученика.|r",
    ["|cffff8800No seal to twist out of. Only Seal of Command and Seal of Righteousness carry over to a swing after being replaced, so one of the two has to be learned.|r"] = "|cffff8800Нет печати, с которой можно менять. Только Печать повеления и Печать праведности всё ещё срабатывают на ударе после замены, поэтому нужна одна из двух.|r",
    ["|cffff8800Only one seal learned. A second one is needed to twist into.|r"] = "|cffff8800Изучена всего одна печать. Для смены нужна вторая.|r",
    ["|cffff8800The seal you hold cannot be twisted out of. Only Seal of Command and Seal of Righteousness carry over to the swing that replaces them.|r"] = "|cffff8800С удерживаемой печати менять нельзя. Только Печать повеления и Печать праведности всё ещё срабатывают на ударе, который их заменяет.|r",
    ["Only Seal of Command and Seal of Righteousness work here: they are the two whose effect still lands on the swing that replaces them."] = "Здесь подходят только Печать повеления и Печать праведности: лишь их действие ещё срабатывает на ударе, который их заменяет.",
    ["Compensate for latency"] = "Учитывать задержку",
    ["Opens the window earlier by one trip to the server, and closes it once the cast can no longer arrive before the swing. Uses your measured world latency, capped at 250 ms."] = "Открывает окно раньше на один путь до сервера и закрывает его, как только накладывание уже не успеет прийти раньше удара. Использует измеренную мировую задержку, не более 250 мс.",
    ["Show out of combat"] = "Показывать вне боя",
    ["Normally the bar is only up in combat. Switch this on to keep it on screen, which is the easier way to practise the timing on a dummy."] = "Обычно полоса видна только в бою. Включите это, чтобы она оставалась на экране — так удобнее отрабатывать тайминг на манекене.",
    -- Namensplaketten-Vorlage
    ["Nameplate settings replaced. Switch profile to get the old ones back."] = "Настройки индикаторов имён заменены. Смените профиль, чтобы вернуть прежние.",
    ["Overwrites this profile's nameplate settings with a wide, flat, dark look. Other profiles are untouched."] = "Перезаписывает настройки индикаторов имён этого профиля широким, плоским и тёмным видом. Другие профили не затрагиваются.",
    ["|cffaaaaaaOverwrites this profile's nameplate settings with a wide, flat, dark look. Other profiles are untouched.|r"] = "|cffaaaaaaПерезаписывает настройки индикаторов имён этого профиля широким, плоским и тёмным видом. Другие профили не затрагиваются.|r",
    ["Apply the wide, flat look"] = "Применить широкий плоский вид",
    -- Plaetze der Namensplaketten
    ["Main positions"] = "Основные позиции",
    ["|cffaaaaaaOne thing per slot. Giving a slot something takes it away from the slot that had it.|r"] = "|cffaaaaaaПо одному на место. То, что ты кладёшь на место, забирается у того, где оно было.|r",
    ["Debuffs"] = "Отрицательные эффекты",
    ["Buffs"] = "Положительные эффекты",
    ["Crowd control"] = "Контроль",
    ["Your own debuffs"] = "Твои отрицательные эффекты",
    -- Leuchten bei wenig Leben, Entzauber-Leuchten
    ["Glow when low on health"] = "Свечение при низком здоровье",
    ["A coloured ring around the bar once the unit drops below the mark."] = "Цветное кольцо вокруг полосы, как только цель опускается ниже отметки.",
    ["Glow below (%)"] = "Свечение ниже (%)",
    ["Low health colour"] = "Цвет при низком здоровье",
    ["Glow in the aura's own school colour"] = "Светиться цветом школы эффекта",
    ["Magic blue, curse purple, disease orange, poison green — instead of one colour for everything."] = "Магия синим, проклятие фиолетовым, болезнь оранжевым, яд зелёным — вместо одного цвета на всё.",
    -- Absorptionsstil
    ["Absorb style"] = "Вид поглощения",
    ["Flat colour"] = "Сплошной цвет",
    -- Zauberziel
    ["Show who the cast is aimed at"] = "Показывать, на кого направлено заклинание",
    ["The caster's current target, beside the cast bar. Your own name is coloured."] = "Текущая цель того, кто читает заклинание, рядом с полосой заклинания. Твоё имя выделяется цветом.",
    ["Cast target size"] = "Размер имени цели заклинания",
    -- Zielpfeile
    ["Arrows beside your target"] = "Стрелки рядом с целью",
    ["Two arrows pointing in at the target's bar, one on each side."] = "Две стрелки, указывающие на полосу цели с обеих сторон.",
    ["Arrow size"] = "Размер стрелок",
    ["Arrow distance"] = "Отступ стрелок",
    ["Arrow colour"] = "Цвет стрелок",
} end)
